(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0008.js"] = [{"id":"poem-35a095130cc70eb787910130","title":"南歌子·庭下新生月","author":"毛滂","dynasty":"宋","verses":["庭下新生月，凭君把酒看。","不须直待素团团。","恰似那人眉样、秀弯环。","冷射鸳鸯瓦，清欺翡翠帘。","数枝烟竹小桥寒。","渐见风吹疏影、过阑干。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-774","tags":[]},{"id":"poem-35a45d279384c3e003e0f4c3","title":"初夏独游南园二首  其二","author":"司马光","dynasty":"宋","verses":["桃李都无日，梧桐半死身。","那堪衰病意，更作独游人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ae76d1b4-8fe9-4010-b306-3bf87c7d3812","tags":[]},{"id":"poem-35a593de38ea6fee9c97368c","title":"挽司直兄  其二","author":"王柏","dynasty":"宋","verses":["典重班诸老，声名始璧流。","开尊口佳士，襥被闯前修。","月冷金闺籍，尘生玉杖鸠。","梅岩伤目处，鴈影正宾秋。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-49fcd16a-8800-4c8f-8fac-72b16f8ecbe1","tags":[]},{"id":"poem-35a6fdf05e926e9517bd2010","title":"闻雪湖张签判讣","author":"释居简","dynasty":"宋","verses":["嘉兴陆长官，遗我尺素书。","报云钧天诏九地，夺我好友张雪湖。","雪湖翩翩上天去，下眎尘滓知何如。","因依未去时，泠然山泽癯。","万象困搜搅，撚断苍髯须。","十年不调闭户居，铁石不受烟火腴。","辟俗如辟豕负涂，后来稍稍低簪裾，百步掩鼻犹反趋。","官高金多娇妻奴，蠛蠓乱眼才斯须。","填门只有长者车，北海尊酒无时无。","明朝一饭欠宿储，印泥指爪嗟鸿鹄。","精明定化为兰菊，纫称骚人陆离佩，英泛绿尊浇魁雷。","骚人之腹秋蝉清，吐芳腾馥日日新。","纷纷郁郁仍轮囷，散为天地无边春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-6be18ec7-34b4-4603-bc12-8b20d213adcc","tags":[]},{"id":"poem-35a8049fac66878edc186072","title":"古意赠梁肃补阙","author":"孟郊","dynasty":"唐","verses":["曲木忌日影，谗人畏贤明。","自然照烛间，不受邪佞轻。","不有百炼火，孰知寸金精。","金铅正同𬬻，愿分精与麤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-fe123ad6-7f8b-4bc9-a03d-16c07efc1358","tags":[]},{"id":"poem-35b4b4448f96c894b9cfa7f3","title":"鹊踏枝","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["刘先主，跳檀溪；雷轰了荐福碑；丙吉教子立起宣帝；老莱子斑衣；包待制上陈州粜米；这一本是《孟母三移》。","(生唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-306","tags":[]},{"id":"poem-35bbc2f8da878602f4825403","title":"浣溪沙·露白蟾明又到秋","author":"顾敻","dynasty":"五代","verses":["露白蟾明又到秋，佳期幽会两悠悠，梦牵情役几时休。","记得泥人微敛黛，无言斜倚小书楼，暗思前事不胜愁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-7","tags":[]},{"id":"poem-35cc5cd83c955b4fc7c7cbcf","title":"郡斋雨中与诸文士燕集","author":"韦应物","dynasty":"唐","verses":["兵卫森画戟，宴寝凝清香。","海上风雨至，逍遥池阁凉。","烦疴近消散，嘉宾复满堂。","自慙居处崇，未覩斯民康。","理会是非遣，性达形迹忘。","鲜肥属时禁，蔬果幸见尝。","俯饮一杯酒，仰聆金玉章。","神欢体自轻，意欲凌风翔。","吴中盛文史，群彦今汪洋。","方知大藩地，岂曰财赋疆。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9f5ded08-4f6f-4641-878e-897904483479","tags":["唐诗三百首","五言古诗","宴会"]},{"id":"poem-35d25cf7d932a02c061a48e9","title":"南歌子·锦荐红㶉𫛶","author":"张泌","dynasty":"五代","verses":["锦荐红㶉𫛶，罗衣绣凤凰。","绮疏飘雪北风狂，帘幕尽垂无事，郁金香。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-49","tags":[]},{"id":"poem-35ddeaf830742f0a55e9b341","title":"明道颂","author":"智闲","dynasty":"唐","verses":["思思似有踪，明明不知处。","借问示宗宾，徐徐暗回顾。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8aefcc1d-13ee-425c-acf5-636d99e9f119","tags":[]},{"id":"poem-35e427de0698c73668ca25fe","title":"减字木兰花·朝云横渡","author":"蒋氏女","dynasty":"宋","verses":["朝云横渡。","辘辘车声如水去。","白草黄沙。","月照孤村三两家。","飞鸿过也。","万结愁肠无昼夜。","渐近燕山。","回首乡关归路难。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-845","tags":[]},{"id":"poem-35e86e59e0988b8be729917a","title":"正之复次前韵作四篇见示是日适登城楼以望江山且阅捷报因赋六章以报之  其一","author":"李纲","dynasty":"宋","verses":["帝遣宗英使楚滨，漕台元自得诗人。","从横锦绣花生舌，飞动龙蛇墨起鳞。","心拱北宸恩露渥，笑回南浦渌波春。","不须过作飞刍计，早晚追陪紫府宾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6af0e915-c382-4177-9ac7-928996776e81","tags":[]},{"id":"poem-35ed34be23c12fb5b9213c37","title":"恋芳春","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［旦止］宝篆香消，绣窗日永，又还节近清明。","暗里时更换，月老逼椿庭，惟愿双亲福寿康宁。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8074","tags":[]},{"id":"poem-35f5c7d6c4b32372825828f3","title":"偶成","author":"程颢","dynasty":"宋","verses":["闲来无事不从容，睡觉东窗日已红。","万物静观皆自得，四时佳兴与人同。","道通天地有形外，思入风云变态中。","富贵不淫贫贱乐，男儿到此是豪雄。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-偶成","tags":[]},{"id":"poem-36097dd927b59989b8b88155","title":"寄题寻真观","author":"李翔","dynasty":"唐","verses":["见说寻真地势雄，面临湖北倚高峰。","奔涛入夏雷声迅，险嶂凌秋黛色浓。","坛上步虚频降鹤，洞中投简数惊龙。","何劳更访桃源路，水曲云深千万重。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e101ee7c-d8d2-4ffa-88a4-b8f18b9e6c4b","tags":[]},{"id":"poem-360cb040ffc917950b26eefc","title":"奉和陆使君长源夏月游太湖","author":"皎然","dynasty":"唐","verses":["庾公心旷远，府事局耳目。","遂与南湖游，虚襟涤烦燠。","始知皇天意，积水在亭育。","细流信不让，动物欣所蓄。","万顷合天容，洗然无云族。","峭蒨瞩仙岭，超遥随明牧。","知公爱澄清，波静气亦肃。","已见横流极，况闻长鲸戮。","中洲暂采苹，南郡思剖竹。","向夕分好风，飘然送归舳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6dfb1fe5-5862-4db0-b3dd-977e7a0992ea","tags":["太湖"]},{"id":"poem-3617266f5ddfb4be374120b4","title":"早寒江上有怀","author":"孟浩然","dynasty":"唐","verses":["木落雁南度，北风江上寒。","我家襄水上，遥隔楚云端。","乡泪客中尽，孤帆天际看。","迷津欲有问，平海夕漫漫。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8e18183e-5a58-4805-b672-1726969d6526","tags":["唐诗三百首","八年级上册(课外)","思归","五言律诗","初中古诗","思乡"]},{"id":"poem-3619727417017ae5b9fb18dc","title":"菩萨蛮 其五","author":"温庭筠","dynasty":"唐","verses":["杏花含露团香雪，绿杨陌上多离别。","灯在月胧明，觉来闻晓莺。","玉钩褰翠幕，妆浅旧眉薄。","春梦正关情，镜中蝉鬓轻。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-4","tags":[]},{"id":"poem-36219d0f38b255ca24961eb0","title":"送人游岭南","author":"司空曙","dynasty":"唐","verses":["万里南游客，交州见柳条。","逢迎人易合，时日酒能消。","浪晓浮青雀，风温解黑貂。","囊金如未足，莫恨故乡遥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d668141d-a638-4b3d-af3a-fee7293fb90c","tags":["写人","告诫","写人诗"]},{"id":"poem-362efa776ed8fd1460c65728","title":"和潞公招尧夫不至","author":"司马光","dynasty":"宋","verses":["东阁樽罍招共饮，后房罗绮约同观。","既无蓟子分身术，须欠车公一座欢。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-7ed3561f-0199-47be-a5cb-dcd4d105cff9","tags":[]},{"id":"poem-363897ca7a46ba9cfa65cc4c","title":"萧宅二三子赠答诗二十首 石再请客","author":"卢仝","dynasty":"唐","verses":["主人若知我，应喜我结得君。","主人不知我，我住何求于主人。","我在天地间，自是一片物。","可得杠压我，使我头不出。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5a26f6d1-4f79-4ee4-ae75-7c4d32ffd227","tags":[]},{"id":"poem-3639f9e6a59b830a796bff5e","title":"冬日寄洛中杨少尹","author":"马戴","dynasty":"唐","verses":["黄河岸柳衰，城下渡流澌。","年长从公懒，天寒入府迟。","家山望几遍，魏阙赴何时。","怀古心谁识，应多谒舜祠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-086e8a34-4c65-42b7-ba57-818cd4eec743","tags":["黄河"]},{"id":"poem-364558a04dd1e07ef71a5f6c","title":"称人心","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["撇呆打堕，早被那人瞧破，要同归知爹肯么？料他每，不见许。","(介)夫人，你缘何独坐？想你爹爹不肯么？伊家道俐齿伶牙，争奈你爹行不可。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5179","tags":[]},{"id":"poem-364aac1d4ba2f1cad05df3d7","title":"新秋","author":"杜甫","dynasty":"唐","verses":["火云犹未敛奇峰，欹枕初惊一叶风。","几处园林萧瑟里，谁家砧杵寂寥中。","蝉声断续悲残月，萤焰高低照暮空。","赋就金门期再献，夜深搔首叹飞蓬。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-新秋","tags":[]},{"id":"poem-364f30d18fbd62d40a74c037","title":"寄秋塘陈敬甫","author":"释居简","dynasty":"宋","verses":["华风岂不声，默与静者吹。","凉月自入袖，默许静者知。","风乎岂必尔，月亦听所之。","静者亦若是，弗与俗子期。","俗方日日浮，静岂忍诡随。","山林隘乾坤，小大各有宜。","思君令人老，一见动岁时。","下塘通上塘，一苇何远而。","畴曩北山日，皂盖松间飞。","澄潜二三子，喜迓见睫眉。","著翁泉上亭，泉石讶久违。","透闸观涛澜，雪溅冰玉澌。","激翁技痒处，汹涌翻文辞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-84cf481d-471f-4826-8be3-7b23cc105a81","tags":[]},{"id":"poem-366094e777635d084636eab8","title":"句  其一","author":"刘望之","dynasty":"宋","verses":["凤林秋晚见日落，鹿门事远无人传。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4514f274-e41d-4aaf-af62-a8580f740822","tags":[]},{"id":"poem-36711a1ea6de4bf5f4918274","title":"虞美人·粉融红腻莲房绽","author":"阎选","dynasty":"五代","verses":["粉融红腻莲房绽，脸动双波慢。","小鱼衔玉鬓钗横，石榴裙染象纱轻，转娉婷。","偷期锦浪荷深处，一梦云兼雨。","臂留檀印齿痕香，深秋不寐漏初长，尽思量。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-19","tags":[]},{"id":"poem-367306ac9d75c9bf9845bd83","title":"忆平泉杂咏 忆寒梅","author":"李德裕","dynasty":"唐","verses":["寒塘数树梅，常近腊前开。","雪映缘岩竹，香侵泛水苔。","遥思清景暮，还有野禽来。","谁是攀枝客，兹辰醉始回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-12029f03-2eaa-44eb-9944-e95e1f178cd8","tags":[]},{"id":"poem-367773ea6ab0a37da72dddfb","title":"采桑子·当时错","author":"纳兰性德","dynasty":"清","verses":["而今才道当时错，心绪凄迷。","红泪偷垂，满眼春风百事非。","情知此后来无计，强说欢期。","一别如斯，落尽梨花月又西。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-45","tags":[]},{"id":"poem-367bae30b9b720cf1cbc012f","title":"立春偶成","author":"张栻","dynasty":"宋","verses":["律回岁晚冰霜少，春到人间草木知。","便觉眼前生意满，东风吹水绿参差。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-立春偶成","tags":[]},{"id":"poem-36896a8ebf2e009295e7a0b8","title":"赠鄠县尉李先辈二首 一","author":"马戴","dynasty":"唐","verses":["同人家鄠杜，相见罢官时。","野坐苔生石，荒居菊入篱。","听蝉临水久，送鹤背山迟。","未拟还城阙，溪僧别有期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-1bb2071b-98be-48f5-9e1a-27abb9a6c105","tags":[]},{"id":"poem-3698135c3e7a633975f98658","title":"赠别越帅蔡侍郎五十韵","author":"华镇","dynasty":"宋","verses":["飞廉鼓橐开氛雺，玉龙盘礴堆苍岫。","云崖左壁出高墉，环回占尽东南秀。","高瞻牛女提封阔，下瞰闾阎烟火富。","紫青岩壑敞屏帏，金碧楼台错纹绣。","城西半规日欲落，天东一缕云如镂。","人间未觉桂华升，林梢先见金波溜。","冰轮冉冉经箕斗，碧落沈沈失星宿。","清光不断万象呈，目极尘寰了无覆。","扶桑欲晓天鸡唱，玉珮丁东咽残漏。","西南松桂碧参差，寒金碎玉高低透。","春和二月融青宙，红紫千花簇繁囿。","香洁蜂蝶夜不知，暗和清影凝罗袖。","暑雨晚随虹影断，炎威夜逼余辉逗。","南湖拂拂起轻飔，鉴光千里冰纨皱。","星流一叶高梧下，玉刻千峰晚山瘦。","桂子香凝零露漙，兔毫冷咽飞泉潄。","六花舞绝平川壤，万树玲珑缀莹琇。","冻云收尽一轮寒，光华上下清交鬭。","明眸朗鉴古难偶，许谢登临亦虚觏。","胜地埋藏祗自奇，千年林下输猿狖。","儒家宗主中郎裔，早掞春华甲英彀。","量阔难穷渤澥远，德馨未羡椒兰臭。","青云有路早徊翔，要津策足频驰骤。","旒扆倾衷聆玉振，经纶溢耳𪭢金奏。","暂虚法从牧远民，大旆高牙会稽首。","庖刃从容经肯綮，鹄卵无劳鲁鸡伏。","探幽索隠有余工，逸胜遗奇落精究。","意匠经营谁与相，壶中风物真天授。","霜斧晨开蔽日林，虹梁晚结飞云搆。","轩窗四辟洞无物，林岭旁来远如走。","佳名一字既惟新，宝墨八法曾非旧。","鹊返鸾徊美无度，龙跳虎卧雄相凑。","何地通宵得佳致，谁人忘寝临觞豆。","西园物色难重逢，秉烛诗词漫三复。","华堂有月终年好，月下樽罍溢醇酎。","坐令越绝山水佳，日添光价高难贸。","五云溪上纶竿手，误指王圻揽缨绶。","画虎年多愧未成，屠龙伎巧伤难售。","清时支离逐斗粟，乐国凄凉寄圭窦。","结巢未忍息南枝，倚辀何计登华厩。","片帆随牒西南迈，尘满儒衣色多垢。","文丽难忘反楚骚，魂交尚冀亲南狩。","昔人富贵志已得，越吟清切伤微疚。","今人徒劳情若何，玉壶慷慨临风叩。","飞盖早容陪后乘，曳裾屡许登文甃。","烟波满眼始凭凌，谈笑回头难邂逅。","吴会他年见桑梓，荆湘数稔包霜柚。","鸣珂应在白沙隄，茇舍徒瞻碧棠茂。","萍迹漂漂渺难系，蓬心慅慅纷奚就。","九疑三五夜晴时，为想堂前皎如昼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-4a6031f7-012b-47a3-99db-b158170281f4","tags":[]},{"id":"poem-36a889cff857a5602988f804","title":"游仙词三十三首  其二五","author":"王镃","dynasty":"宋","verses":["灵液长流满地香，洞中多是散仙房。","金炉煮就金精汁，欲献元君未敢尝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-ff370246-3948-401f-b869-453d3868398c","tags":[]},{"id":"poem-36b84d5ebdecea6793a9e607","title":"尾声","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(合)四时游赏多欢宴，三公不换此芳年，也是我和你夙世修来百福全。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1741","tags":[]},{"id":"poem-36db1a919ed37664c8745f7f","title":"宴左山二首  其一","author":"刘跂","dynasty":"宋","verses":["闰冬节物晏，十月犹素秋。","招提阳冈路，宛在岘山头。","史君有高致，尊酒擅一丘。","欢颜动长啸，松菊含春柔。","风清宿雾断，地迥行潦收。","时令将凛落，飞光为谁留。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-b7ca0763-70a8-4e00-b5e9-a656ed82216c","tags":[]},{"id":"poem-36e28eea07484f6fc0df4256","title":"望海楼","author":"米芾","dynasty":"宋","verses":["云间铁瓮近青天，缥缈飞楼百尺连。","三峡江声流笔底，六朝帆影落尊前。","几番画角催红日，无事沧洲起白烟。","忽忆赏心何处是，春风秋月两茫然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-7994cb6e-a1aa-415c-81db-f091905948c1","tags":["咏物诗","咏物","写景"]},{"id":"poem-36e3084dc5d54a0cc6fe1863","title":"别石泉","author":"李绅","dynasty":"唐","verses":["素沙见底空无色，青石潜流暗有声。","微渡竹风涵淅沥，细浮松月透轻明。","桂凝秋露添灵液，茗折香芽泛玉英。","应是梵宫连洞府，浴池今化醒泉清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-1e3d60b9-9a69-4da7-91c3-0e9664914292","tags":[]},{"id":"poem-36e969dd12534c342c8ce00d","title":"进宣宗收复河湟诗","author":"崔铉","dynasty":"唐","verses":["边陲万里注恩波，宇宙群芳洽凯歌。","右地名王争解辫，远方戎垒尽投戈。","烟尘永息三秋戍，瑞气遥清九折河。","共遇圣明千载运，更观俗阜与时和。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-0f0946e8-326e-4554-8826-8ecbc07bcc86","tags":[]},{"id":"poem-36f1b01669e863f71e852b38","title":"赠实际英上人","author":"吕江","dynasty":"宋","verses":["实际即为诚，中庸说著形。","晓来雷雨过，七十二峰青。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b534542d-43d2-41da-a113-c0031761c0c2","tags":[]},{"id":"poem-36f2805fcd5d9d8ce88cd891","title":"送河西从事","author":"张乔","dynasty":"唐","verses":["结束佐戎旃，河西住几年。","陇头随日去，碛里寄星眠。","水近沙连帐，程遥马入天。","圣朝思上策，重待奏安边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0879d94f-3cc1-4458-8bcf-3b5d2206cb08","tags":[]},{"id":"poem-36f4fadb857c76ead522ea14","title":"送李翺习之","author":"孟郊","dynasty":"唐","verses":["习之势翩翩，东南去遥遥。","赠君双履足，一为上臯桥。","臯桥路逶迤，碧水清风飘。","新秋折藕花，应对吴语娇。","千巷分渌波，四门生早潮。","湖榜轻褭褭，酒旗高寥寥。","小时屐齿痕，有处应未销。","旧忆如雾星，怳见于梦消。","言之烧人心，事去不可招。","独孤宅前曲，箜篌醉中谣。","壮年俱悠悠，逮兹各焦焦。","执手复执手，唯道无枯凋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-8399a509-3f09-4027-a389-f5c4ba9e5dfe","tags":[]},{"id":"poem-3700dbdaec166b81f69d3de0","title":"送沈学士守毗陵","author":"苏颂","dynasty":"宋","verses":["使君四十五专城，新向鸿都得请行。","高阁和铅人暂去，秋郊驱弩吏趋迎。","兰陵郡邑今尤盛，阳羡溪山古有名。","赋政优游多乐事，东园应不负飞觥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ce3dd7bd-25b8-4d19-8c66-d000284aa46b","tags":[]},{"id":"poem-3702ddfb026d518d7e333d0d","title":"发襄阳后却寄公安人","author":"包佶","dynasty":"唐","verses":["挥泪送回人，将书报所亲。","晚年多疾病，中路有风尘。","王粲频征楚，君恩许入秦。","还同星火去，马上别江春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b0e238eb-b1b5-4edb-820b-e5cc8b6481e1","tags":[]},{"id":"poem-37048f0f2e271389e602c74a","title":"宫词  其一三","author":"张公庠","dynasty":"宋","verses":["仙籞梅开淡淡春，夜来微雨渗轻尘。","风和日暖难凋落，不怕倚楼吹笛人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d3d71fd6-1d25-4569-951f-98da29b1dfa7","tags":[]},{"id":"poem-371ee7684a932bdb6c6bca8f","title":"偈颂六十七首  其一二","author":"释原妙","dynasty":"宋","verses":["师子窟，师子吼。","师子儿，无前后。","蓦然直下翻身，便解人前开口。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-4a3be4cb-41b9-401c-97a2-dadac049bfae","tags":[]},{"id":"poem-3722e5894dd8469b26a536f5","title":"采菽","author":"佚名","dynasty":"先秦","verses":["采菽采菽，筐之莒之。君子来朝，何锡予之？虽无予之？路车乘马。又何予之？玄衮及黼。","觱沸槛泉，言采其芹。君子来朝，言观其旗。其旗淠淠，鸾声嘒嘒。载骖载驷，君子所届。","赤芾在股，邪幅在下。彼交匪纾，天子所予。乐只君子，天子命之。乐只君子，福禄申之。","维柞之枝，其叶蓬蓬。乐只君子，殿天子之邦。乐只君子，万福攸同。平平左右，亦是率从。","泛泛杨舟，绋𫄥维之。乐只君子，天子葵之。乐只君子，福禄膍之。优哉游哉，亦是戾矣。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-221","tags":[]},{"id":"poem-372361324715471e730dede2","title":"药山三咏 伏牛庵","author":"李纲","dynasty":"宋","verses":["侍者何须召二空，一元调伏自知风。","轩然栋宇翚飞处，何似当年茅竹中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-52a64c4a-c964-4c9f-a287-e2436cc965f0","tags":[]},{"id":"poem-3725caaf36878ce6f2f32322","title":"寄王赞学","author":"司空图","dynasty":"唐","verses":["黄卷不关兼济业，青山自保老闲身。","一行万里纤尘静，可要张仪更入秦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0092ded3-c8f1-48bd-a28e-4d1c40081910","tags":[]},{"id":"poem-37309573899aea19921a5aa5","title":"浣溪沙·桃杏风香帘幕闲","author":"孙光宪","dynasty":"五代","verses":["桃杏风香帘幕闲，谢家门户约花关，画梁幽语燕初还。","绣阁数行题了壁，晓屏一枕酒醒山，却疑身是梦魂间。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-38","tags":[]},{"id":"poem-3734843341e8eb2601298506","title":"维清","author":"佚名","dynasty":"先秦","verses":["维清缉熙，文王之典。肇禋，迄用有成，维周之祯。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-267","tags":[]},{"id":"poem-373725b4441b0fee1750a04e","title":"浣溪沙·艳赵倾燕花里仙","author":"向子𬤇","dynasty":"宋","verses":["艳赵倾燕花里仙。","乌丝阑写永和年。","有时闲弄醒心弦。","茗碗分云微醉后，纹楸斜倚髻鬟偏。","风流模样总堪怜。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-792","tags":[]},{"id":"poem-373c808d491455f635856c8c","title":"上巳日赐裴度","author":"文宗皇帝","dynasty":"唐","verses":["注想待元老，识君恨不早。","我家柱石衰，忧来学丘祷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-9b99f129-4039-41f1-b8db-b12d21035fc2","tags":[]},{"id":"poem-37426bf1a6d770d042d6e1a8","title":"自蒲圻临湘趋岳阳道中作十首  其九","author":"李纲","dynasty":"宋","verses":["俎豆其如军旅何，谁令瀚海起干戈。","休将直道论三黜，且把微辞续九歌。","山鬼含颦乘赤豹，湘灵解珮鼓云和。","蛮邦虽陋吾何恨，厌见旌蕤相荡摩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c1a3062d-b8ab-4895-a256-a1521d1275b0","tags":[]},{"id":"poem-37460d350b3286a09c22876e","title":"将过江题白沙馆","author":"徐铉","dynasty":"宋","verses":["少长在维扬，依然认故乡。","金陵佳丽地，不道少风光。","稍望吴台远，行登楚塞长。","殷勤语江岭，归梦莫相妨。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-4813c5ab-b686-478b-b041-b5324c0f549a","tags":[]},{"id":"poem-3749271f4cc8444fe541f56e","title":"长相思·红疏疏","author":"王质","dynasty":"宋","verses":["红疏疏，紫疏疏。","可惜飘零著地铺。","春残心转孤。","莺相呼。","燕相呼。","楼下垂杨遮得乌。","倚阑人已无。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-306","tags":[]},{"id":"poem-374a0e736d9f4d2beeb66c79","title":"拟冬日景忠山应制·雄关阻塞戴灵鳌","author":"纳兰性德","dynasty":"清","verses":["雄关阻塞戴灵鳌，控制卢龙胜百牢。","山界万重横翠黛，海当三面涌银涛。","哀笳带月传声切，早雁迎秋度影高。","旧是六师开险处，待陪巡幸扈星旌。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-253","tags":[]},{"id":"poem-374a8830610c81f98d824f15","title":"莺啼序·残寒正欺病酒","author":"吴文英","dynasty":"宋","verses":["残寒正欺病酒，掩沈香绣户。","燕来晚、飞入西城，似说春事迟暮。","画船载、清明过却，晴烟冉冉吴宫树。","念羁情游荡，随风化为轻絮。","十载西湖，傍柳系马，趁娇尘软雾。","溯红渐、招入仙溪，锦儿偷寄幽素。","倚银屏、春宽梦窄，断红湿、歌纨金缕。","暝堤空，轻把斜阳，总还鸥鹭。","幽兰旋老，杜若还生，水乡尚寄旅。","别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。","长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。","青楼彷佛，临分败壁题诗，泪墨惨澹尘土。","危亭望极，草色天涯，吹鬓侵半苎。","暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。","殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。","伤心千里江南，怨曲重招，断魂在否。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-8","tags":["宋词三百首","西湖"]},{"id":"poem-3754d28f5000a76e43ac8a46","title":"遣兴五首 三","author":"杜甫","dynasty":"唐","verses":["漆有用而割，膏以明自煎。","兰摧白露下，桂折秋风前。","府中罗旧尹，沙道尚依然。","赫赫萧京兆，今为时所怜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-4cc0678f-1272-47ec-89ed-233fee07d436","tags":[]},{"id":"poem-375be0a80eb9d7fd41759c3c","title":"白菊三首 三","author":"司空图","dynasty":"唐","verses":["为报繁霜且莫催，穷秋须到自低垂。","横拖长袖招人别，只待春风却舞来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-24629e4a-bb7a-49cc-b65d-74e1c4302908","tags":[]},{"id":"poem-375e11c6b87edf2380a2f104","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(净)兄饮一杯，但从今放开忧虑，兄有事弟当前去。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1699","tags":[]},{"id":"poem-37675fb40165081bb6074185","title":"薄暮步村径","author":"吕从庆","dynasty":"唐","verses":["竹里荆扉掩，村前万物幽。","飞虫抟涧舞，鸣鹊抱巢修。","川上渔歌断，坡前牧课休。","淡烟随杖履，吾意自悠悠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-59a32830-79c2-4176-b0f9-c15f449dde45","tags":[]},{"id":"poem-3768945cdbbdf96d601866ac","title":"恸柳论","author":"刘言史","dynasty":"唐","verses":["孀妻栖户仍无嗣，欲访孤坟谁引至。","裴回无处展哀情，惟有衣襟知下泪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-86fd8d10-6861-4018-ad11-7e711ea2ef44","tags":[]},{"id":"poem-376fc9b31ef59c6dcf6473db","title":"雨中花慢·缥蒂缃枝","author":"刘褒","dynasty":"宋","verses":["缥蒂缃枝，玉叶翡英，百梢争赴春忙。","正雨后、蜂黏落絮，燕扑晴香。","遗策谁家荡子，唾花何处新妆。","想流红有恨，拾翠无心，往事凄凉。","春愁如海，客思翻空，带围只看东阳。","更那堪、玉笙度曲，翠羽传觞。","红泪不胜闺怨，白云应老他乡。","梦回羁枕，风惊庭树，月在西厢。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-304","tags":[]},{"id":"poem-377171d694344dc0b350d66c","title":"蓦山溪·山明水秀","author":"黄庭坚","dynasty":"宋","verses":["山明水秀，尽属诗人道。","应是五陵儿，见衰翁、孤吟绝倒。","一觞一咏，潇洒寄高闲，松月下，竹风间，试想为襟抱。","玉关遥指，万里天衢杳。","笔阵扫秋风，泻珠玑、琅琅皎皎。","卧龙智略，三诏佐升平，烟塞事，玉堂心，频把菱花照。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-749","tags":[]},{"id":"poem-378363cdd4da82daccf7f9d3","title":"小重山·绿树莺啼春正浓","author":"何大圭","dynasty":"宋","verses":["绿树莺啼春正浓。","钗头青杏小，绿成丛。","玉船风动酒鳞红。","歌声咽，相见几时重。","车马去匆匆。","路随芳草远，恨无穷。","相思只在梦魂中。","今宵月，偏照小楼东。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-216","tags":[]},{"id":"poem-3791748b5d98c721709d5080","title":"木兰花・玉楼春·檀槽碎响金丝拨","author":"张先","dynasty":"宋","verses":["檀槽碎响金丝拨。","露湿浔阳江上月。","不知商妇为谁愁，一曲行人留晚发。","画堂花入新声别。","红蕊调高弹未彻。","暗将深意语胶弦，长愿弦丝无断绝。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-365","tags":[]},{"id":"poem-3795491fa7b49ba022a1eef1","title":"郊坛回舆中书二相公蒙圣慈召至御马前仰感恩遇辄书是诗兼呈二相公","author":"李德裕","dynasty":"唐","verses":["七萃和銮动，三条葆吹回。","相星环日道，苍马近龙媒。","咫尺天颜接，光华喜气来。","自慙衰且病，无以效涓埃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7ac67f4d-49cf-4ccc-9bfe-d34d96095800","tags":[]},{"id":"poem-379b3c6d8022a834e391f757","title":"偶诗五首 二","author":"司空图","dynasty":"唐","verses":["芙蓉骚客空留怨，芍药诗家只寄情。","谁似天才李山甫，牡丹属思亦纵横。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-bde32250-e1f6-407d-bd49-a2ec23eabb8b","tags":[]},{"id":"poem-379b612058d3dd942a1522eb","title":"江汉","author":"佚名","dynasty":"先秦","verses":["江汉浮浮，武夫滔滔。匪安匪游，淮夷来求。既出我车，既设我旟。匪安匪舒，淮夷来铺。","江汉汤汤，武夫洸洸。经营四方，告成于王。四方既平，王国庶定。时靡有争，王心载宁。","江汉之浒，王命召虎：式辟四方，彻我疆土。匪疚匪棘，王国来极。于疆于理，至于南海。","王命召虎：来旬来宣。文武受命，召公维翰。无曰予小子，召公是似。肇敏戎公，用锡尔祉。","厘尔圭瓒，秬鬯一卣。告于文人，锡山土田。于周受命，自召祖命，虎拜稽首：天子万年！","虎拜稽首，对扬王休。作召公考：天子万寿！明明天子，令闻不已，矢其文德，洽此四国。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-261","tags":[]},{"id":"poem-379cede9b2456430823bde5f","title":"杂题二首 一","author":"司空图","dynasty":"唐","verses":["先知左袒始同行，须待龙楼羽翼成。","若使只凭三杰力，犹应汉鼎一毫轻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-1773dc56-420a-4e73-b4c4-5adfff1cb1d0","tags":[]},{"id":"poem-379d47596b0a12d295984316","title":"饯唐永昌","author":"沈佺期","dynasty":"唐","verses":["洛阳旧有神明宰，辇毂由来天地中。","余邑政成何足贵，因君取则四方同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-bb771da6-427d-437a-856a-4a7826c74b1a","tags":[]},{"id":"poem-37a14154c8309b78302281ad","title":"和韦开州盛山十二首 宿云亭","author":"张籍","dynasty":"唐","verses":["清净当深处，虚明向远开。","卷帘无俗客，应只见云来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3e7e656b-5ca2-4dbc-972f-0369be5046b8","tags":[]},{"id":"poem-37a22ee91a32150aee96cf89","title":"九日寄岑参","author":"杜甫","dynasty":"唐","verses":["出门复入门，两脚但如旧。","所向泥活活，思君令人瘦。","沈吟坐西轩，饮食错昏昼。","寸步曲江头，难为一相就。","吁嗟呼苍生，稼穑不可救。","安得诛云师，畴能补天漏。","大明韬日月，旷野号禽兽。","君子强逶迤，小人困驰骤。","维南有崇山，恐与川浸溜。","是节东篱菊，纷披为谁秀。","岑生多新诗，性亦嗜醇酎。","采采黄金花，何由满衣袖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7c5fb4a5-5b1f-4eff-8e7f-a59f35d9d835","tags":["怀人","重阳节"]},{"id":"poem-37a63c977638b2872bdcad25","title":"寄钟谟","author":"徐铉","dynasty":"宋","verses":["看看潘鬓二毛生，昨日林梢又转鶑。","欲对春风忘世虑，敢言罇酒召时英。","假中西阁应无事，筵上南威幸有情。","不得车公终不乐，已教红袖出门迎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-5e61c18c-0042-48ef-8751-32ab5a224143","tags":[]},{"id":"poem-37ab3bd45196c0f332f955ec","title":"立高桂坊","author":"王十朋","dynasty":"宋","verses":["书生未折桂，短檠事然膏。","一朝桂入手，不记灯窗劳。","回视纸上语，弃置等弁髦。","曲学如公孙，高第何足褒。","温陵号多士，呦呦食苹蒿。","胪唱十年间，魁亚出二豪。","向来此坊中，一门五梦刀。","月中仙子归，天香满蓝袍。","大对压晁董，同登尽刘曹。","嘉名换扁榜，铁画新挥毫。","我欲成其美，远大期伊臯。","桂高固可喜，更看名节高。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-182e76f6-f014-4d7d-99e6-442b728c5c97","tags":[]},{"id":"poem-37abb93f992e56b11962cc16","title":"闻猨","author":"苏拯","dynasty":"唐","verses":["秋风飒飒猨声起，客恨猨哀一相似。","漫向孤危惊客心，何曾解入笙歌耳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-82364db2-abc9-4de7-8d21-13c8475f4f63","tags":[]},{"id":"poem-37c0d227295a47ce108383ea","title":"夜得岳后庵僧家园新茶甚不多辄分数椀奉伯承","author":"张栻","dynasty":"宋","verses":["小园茶树数十许，走寄萌芽初得尝。","虽无山顶烟岚润，亦有灵泉一派香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-929bb59b-e37b-4344-9681-c7e729b4e7f8","tags":[]},{"id":"poem-37c3eb82b8cfba0cfef43727","title":"同皇甫冉登重玄阁","author":"李嘉祐","dynasty":"唐","verses":["高阁朱栏不厌游，蒹葭白水遶长洲。","孤云独鸟川光暮，万井千山海色秋。","清梵林中人转静，夕阳城上角偏愁。","谁怜远作秦吴别，离恨归心双泪流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-defb1a3b-499d-47da-b4ed-e397a921753e","tags":[]},{"id":"poem-37c73a5dcaaac79a01fb4cf8","title":"缕缕金","author":"徐田臣《杀狗记》","dynasty":"元","verses":["你平白地将咱赶出门，杀人来唤我去埋形。","你今打些不干净，须要对证。","(生、旦作慌介。","小生)唬得他夫妇战兢兢，一个个胆丧心惊。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1917","tags":[]},{"id":"poem-37cd1e772a7a35406ca6be98","title":"山花","author":"李涉","dynasty":"唐","verses":["六出花开赤玉盘，当中红湿耐春寒。","长安若在五侯宅，谁肯将钱买牡丹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-06c5b925-7d25-4399-8830-586a37ccc559","tags":[]},{"id":"poem-37d36f148af8b610c7c20b47","title":"昔昔盐二十首 前年过代北","author":"赵嘏","dynasty":"唐","verses":["代北几千里，前年又复经。","燕山云自合，胡塞草应青。","铁马喧鼙鼓，蛾眉怨锦屏。","不知羌笛曲，掩泪若为听。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-58dfc7b8-98f9-480c-8a1c-36352ddbece5","tags":[]},{"id":"poem-37d6e29c8ef50231c78c1e77","title":"酬刘员外月下见寄","author":"章八元","dynasty":"唐","verses":["夜凉河汉白，卷箔出南轩。","过月鸿争远，辞枝叶暗翻。","独谣闻丽曲，缓步接清言。","宣室思前席，行看拜主恩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1d371211-04bf-43d5-a5fd-39d664a176b7","tags":[]},{"id":"poem-37f03444b7edfed0bceeeb92","title":"沁园春·瞬息浮生","author":"纳兰性德","dynasty":"清","verses":["丁巳重阳前三日，梦亡妇淡妆素服，执手硬咽。","语多不复能。","但临别有云：“衔恨愿为天上月，年年犹得向郎圆”","妇素未工诗，不知何以得此也。","觉后感赋长调:。","瞬息浮生，薄命如斯，低徊怎忘？","记绣榻闲时，并吹红雨，雕阑曲处，同倚斜阳。","梦好难留，诗残莫续，赢得更深哭一场。","遗容在，只灵飙一转，未许端详。","重寻碧落茫茫，料短发，朝来定有霜。","便人间天上，尘缘未断，春花秋叶，触绪还伤。","欲结绸缪，翻惊摇落，减尽荀衣昨日香。","真无奈，倩声声邻笛，谱出回肠。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-96","tags":[]},{"id":"poem-37f5a38e707b186f3bc8df69","title":"送裴相公赴镇太原","author":"张籍","dynasty":"唐","verses":["盛德雄名远近知，功高先乞守藩维。","衔恩暂遣分龙节，署勅还同在凤池。","天子亲临楼上送，朝官齐出道傍辞。","明年塞北清蕃落，应建生祠请立碑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-781555b7-0c60-4783-9639-1609adb59969","tags":[]},{"id":"poem-38020a0fbf4c9b2cfce5b01b","title":"惜馀欢・惜余欢·四时美景","author":"黄庭坚","dynasty":"宋","verses":["四时美景，正年少赏心，频启东阁。","芳酒载盈车，喜朋侣簪合。","杯觞交飞劝酬献，正酣饮、醉主公陈榻。","坐来争奈，玉山未颓，兴寻巫峡。","歌阑旋烧绛蜡。","况漏转铜壶，烟断香鸭。","犹整醉中花，借纤手重插。","相将扶上，金鞍騕袅，碾春焙、愿少延欢洽。","未须归去，重寻艳歌，更留时霎。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-761","tags":[]},{"id":"poem-380247d6c859876252a22787","title":"正月闺情","author":"袁晖","dynasty":"唐","verses":["正月金闺里，微风绣户间。","晓魂怜别梦，春思逼啼颜。","遶砌梅堪折，当轩树未攀。","岁华庭北上，何日度阳关。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-bea50743-fb46-4fc0-94c0-0e8fc05f5294","tags":[]},{"id":"poem-38032510690d90c77a053cd8","title":"春日留别","author":"张籍","dynasty":"唐","verses":["游人欲别离，半醉对花枝。","看著春又晚，莫轻少年时。","临行记分处，廻首是相思。","各向天涯去，重来未可期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7ca34906-4e7e-482e-9466-22d89a5f87ec","tags":[]},{"id":"poem-380499e076e39c7f379a1964","title":"荷叶杯·一去又乖期信","author":"顾敻","dynasty":"五代","verses":["一去又乖期信，春尽。","满院长莓苔，手挼裙带独徘徊。","来么来，来么来。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-29","tags":[]},{"id":"poem-3806cb00340807b21109ac3b","title":"蝶恋花·月皎惊乌栖不定","author":"周邦彦","dynasty":"宋","verses":["月皎惊乌栖不定。","更漏将残，辘，牵金井。","唤起两眸清炯炯。","泪花落枕红棉泠。","执手霜风吹鬓影。","去意徊徨，别语愁难听。","楼上阑干横斗柄。","露寒人远鸡相应。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-242","tags":["宋词三百首"]},{"id":"poem-38082f85e6a28225eb0419d9","title":"月夕有怀","author":"崔道融","dynasty":"唐","verses":["圆光照一海，远客在孤舟。","相忆无期见，中宵独上楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-974b9ab5-5e91-4a0c-a515-f9516043ab2d","tags":[]},{"id":"poem-380c426cd16c9aa40aea7d67","title":"风流子·楼倚长衢欲暮","author":"孙光宪","dynasty":"五代","verses":["楼倚长衢欲暮，簪见神仙伴侣。","微傅粉，拢梳头，隐映画帘开处。","无语，无绪，慢曳罗裙归去。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-26","tags":[]},{"id":"poem-3815ceea90133f20b840e2f1","title":"清平调 一","author":"李白","dynasty":"唐","verses":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-948fa40a-492e-4fa1-99f4-b002ae87cd24","tags":["女子","唐诗三百首","乐府","赞美","近代曲辞"]},{"id":"poem-381e436f5cae9bbcc46fecb4","title":"立秋日题安昌寺北山亭","author":"孙逖","dynasty":"唐","verses":["楼观倚长霄，登攀及霁朝。","高如石门顶，胜拟赤城标。","天路云虹近，人寰气象遥。","山围伯禹庙，江落伍胥潮。","徂暑迎秋薄，凉风是日飘。","果林余苦李，萍水覆甘蕉。","览古嗟夷漫，凌空爱泬寥。","更闻金刹下，钟梵晚萧萧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-814d2107-c19e-4287-87cb-e17cde697893","tags":[]},{"id":"poem-38238930f57486c045c24e47","title":"上行杯·离棹逡巡欲动","author":"孙光宪","dynasty":"五代","verses":["离棹逡巡欲动，临极浦，故人相送，去住心情知不共。","金船满捧。绮罗愁，丝管咽。回别，帆影灭，江浪如雪。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-37","tags":[]},{"id":"poem-382fbd587a85d3defccad662","title":"宋中遇林卢杨十七山人因而有别","author":"高适","dynasty":"唐","verses":["昔余涉漳水，驱车行邺西。","遥见林虑山，苍苍戛天倪。","邂逅逢尔曹，说君彼岩栖。","萝径垂野蔓，石房倚云梯。","秋韭何青青，药苗数百畦。","栗林隘谷口，栝树森廻谿。","耕耘有山田，纺绩有山妻。","人生苟如此，何必组与珪。","谁谓远相访，曩情殊不迷。","簷前举醇醪，灶下烹双鸡。","朔风忽振荡，昨夜寒螀啼。","游子益思归，罢琴伤解携。","出门尽原野，白日黯已低。","始惊道路难，终念言笑暌。","因声谢岑壑，岁暮一攀跻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-83de3747-2242-4ae3-be3e-56a7b040aae2","tags":[]},{"id":"poem-38354d5d1ac7d07728f018de","title":"马嵬","author":"崔道融","dynasty":"唐","verses":["万乘凄凉蜀路归，眼前珠翠与心违。","重华不是风流主，湘水犹传泣二妃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2b15cfb0-61fb-4081-aa00-3504ea2c69f4","tags":[]},{"id":"poem-3837154ee222a38377f1dec9","title":"相见欢·十年湖海扁舟","author":"毛滂","dynasty":"宋","verses":["十年湖海扁舟。","几多愁。","白发青灯今夜、不宜秋。","中庭树。","空阶雨。","思悠悠。","寂寞一生心事、五更头。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-903","tags":[]},{"id":"poem-384a4421691d0a952bb7ef3e","title":"浣溪沙·百花丛里试新妆","author":"韩淲","dynasty":"宋","verses":["百花丛里试新妆。","不许巫山枉断肠。","牡丹风扬曲声长。","寒食清明闲节序，绮窗朱户少年场。","燕泥香润落空梁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-486","tags":[]},{"id":"poem-384b1356ec2df897998aa798","title":"渔家傲·七月新秋风露早","author":"欧阳修","dynasty":"宋","verses":["七月新秋风露早。","渚莲尚拆庭梧老。","是处瓜华时节好。","金尊倒。","人间采缕争祈巧。","万叶敲声凉乍到。","百虫啼晚烟如扫。","箭漏初长天杳杳。","人语悄。","那堪夜雨催清晓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-701","tags":[]},{"id":"poem-3859d3a9f76ad18d11945c1c","title":"大明","author":"佚名","dynasty":"先秦","verses":["明明在下，赫赫在上。天难忱斯，不易维王。天位殷适，使不挟四方。","挚仲氏任，自彼殷商，来嫁于周，曰嫔于京。乃及王季，维德之行。","大任有身，生此文王。维此文王，小心翼翼。昭事上帝，聿怀多福。厥德不回，以受方国。","天监在下，有命既集。文王初载，天作之合。在洽之阳，在渭之涘。","文王嘉止，大邦有子。大邦有子，伣天之妹。文定厥祥，亲迎于渭。造舟为梁，不显其光。","有命自天，命此文王。于周于京，缵女维莘。长子维行，笃生武王。保右命尔，燮伐大商。","殷商之旅，其会如林。矢于牧野，维予侯兴。上帝临女，无二尔心。","牧野洋洋，檀车煌煌，驷𫘪彭彭。维师尚父，时维鹰扬。凉彼武王，四伐大商，会朝清明。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-235","tags":[]},{"id":"poem-3866747b6fbc5fc146045db9","title":"句","author":"后主衍","dynasty":"唐","verses":["不缘朝阙去，好此结茅庐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-10dd38a5-9bf1-4b83-b898-4692f718f0d7","tags":[]},{"id":"poem-386ab6792c4107f4e3f1bd4c","title":"和韦开州盛山十二首 流杯渠","author":"张籍","dynasty":"唐","verses":["渌酒白螺杯，随流去复回。","似知人把处，各向面前来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2c498561-27a0-447d-86fc-ad0232f9ee43","tags":[]},{"id":"poem-386c5921b55eed84605468b3","title":"庆全庵桃花","author":"谢枋得","dynasty":"宋","verses":["寻得桃源好避秦，桃红又是一年春。","花飞莫遣随流水，怕有渔郎来问津。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-慶全庵桃花","tags":[]},{"id":"poem-386d2deea615656534afde5b","title":"寓意","author":"晏殊","dynasty":"宋","verses":["油壁香车不再逢，峡云无迹任西东。","梨花院落溶溶月，柳絮池塘淡淡风。","几日寂寥伤酒后，一番萧瑟禁烟中。","鱼书欲寄何由达，水远山长处处同。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-寓意","tags":[]},{"id":"poem-387190173a393b7d3fe82394","title":"送南客","author":"张籍","dynasty":"唐","verses":["行路雨修修，青山尽海头。","天涯人去远，岭北水空流。","夜市连铜柱，巢居属象州。","来时旧相识，谁向日南游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ad33bfc2-7b45-48ee-b3ca-3891ab32a9f5","tags":[]},{"id":"poem-388666bb138319b220179bd9","title":"敦煌廿咏（并序） 二十、分流泉咏","author":"敦煌人作品[一]","dynasty":"唐","verses":["地涌澄泉美，环城本自奇。","一源分异派，两道入汤池。","波上青苹合，洲前翠柳垂。","况逢佳景处，从此遂忘疲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7c8ec13f-3747-4e24-9c24-b49274e01b3f","tags":[]},{"id":"poem-38877a5a1144c935ed33585b","title":"临江仙·碧染长空池似镜","author":"顾敻","dynasty":"五代","verses":["碧染长空池似镜，倚楼闲望凝情，满衣红藕细香清。","象床珍簟，山障掩，玉琴横。","暗想昔时欢笑事，如今赢得愁生。","博山炉暖淡烟轻。","蝉吟人静，残日傍，小窗明。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-31","tags":[]},{"id":"poem-388f56f00741180322609103","title":"听绍上人琴","author":"释居简","dynasty":"宋","verses":["悠然勇变划然鸣，古恨沉沉易水生。","短发不禁愁触绪，恰如猿叫第三声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-741960cf-ad91-4fe1-8ea3-3bf1733016cc","tags":[]},{"id":"poem-3893228de6b0a477cd527d74","title":"借车","author":"孟郊","dynasty":"唐","verses":["借车载家具，家具少于车。","借者莫弹指，贫穷何足嗟。","百年徒役走，万事尽随花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-638d5260-6bc2-4256-9d58-725fa76e2576","tags":[]},{"id":"poem-38952e24bb6fce38b92d7c40","title":"郊庙歌辞 五郊乐章 黑帝羽音 雍和","author":"魏征","dynasty":"唐","verses":["阳月斯纪，应钟在候。","载洁牲牷，爰登俎豆。","既高既远，无声无臭。","静言格思，惟神保祐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-db05caa8-e760-4912-9bd2-d17b2764abe8","tags":[]},{"id":"poem-3898d8b60324fdaf1ff1e6c8","title":"虞美人·柳梢梅萼春全未","author":"张孝祥","dynasty":"宋","verses":["柳梢梅萼春全未。","谁曾伤春意。","一年好处是新春。","柳底梅边只欠、那人人。","凭春约住梅和柳。","略待些时候。","锦帆风送彩舟来。","却遗香包娇叶、一齐开。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-249","tags":[]},{"id":"poem-38a000497bcfeb82e74b615d","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二","author":"易静","dynasty":"唐","verses":["看天马，辰戌亦同前。","（京本注：「魁罡也。","」）若在支干（京本作「干支」）应空（辛本、川本、京本作「定」）发，更还加季不（京本作「主」）留连，人马闹（京本作「更」）喧喧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8fc5c611-cd5c-45f2-abc6-d0e59d4dc8d3","tags":[]},{"id":"poem-38a49b0c485a28ecfd0fec1e","title":"奉和右省仆射西亭高卧作","author":"徐铉","dynasty":"宋","verses":["院静苍苔积，庭幽怪石欹。","蝉声当槛急，虹影向簷垂。","昼漏犹怜永，丛兰未觉衰。","疏篁巢翡翠，折苇覆鸬鹚。","对酒襟怀旷，围棋旨趣迟。","景皆随所尚，物各遂其宜。","道与时相会，才非民所羁。","赋诗贻座客，秋事尔何悲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-54dec904-89ad-48ee-86b5-328c123025c6","tags":[]},{"id":"poem-38ab95a47faa09dff5595949","title":"渝州逢故人（「渝州」，原作「滁州」，从原卷改。）","author":"胡皓","dynasty":"唐","verses":["共是他乡客，俱为失路人。","自怜蓬髪改，不掩柳条春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-b6814928-84c3-43d0-8c00-e0373f7371e7","tags":[]},{"id":"poem-38b07ddf16f799e4b9bce6fe","title":"和贺兰判官望北海作","author":"高适","dynasty":"唐","verses":["圣代务平典，𬨎轩推上才。","迢遥溟海际，旷望沧波开。","四牡未遑息，三山安在哉。","巨鼇不可钓，高浪何崔嵬。","湛湛朝百谷，茫茫连九垓。","挹流纳广大，观异增迟廻。","日出见鱼目，月圆知蚌胎。","迹非想像到，心以精灵猜。","远色带孤屿，虚声涵殷雷。","风行越裳贡，水遏天吴灾。","揽辔隼将击，忘机鸥复来。","缘情韵骚雅，独立遗尘埃。","吏道竟殊用，翰林仍忝陪。","长鸣谢知己，所媿非龙媒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ec8e6f54-f69f-43a9-ab8b-155ff46ce8f2","tags":[]},{"id":"poem-38b0c1ec43bcc12cf7c0a275","title":"扶南曲歌词五首 三","author":"王维","dynasty":"唐","verses":["香气传空满，妆华影箔通。","歌闻天仗外，舞出御楼中。","日暮归何处，花间长乐宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-628b0aeb-ace3-4f3b-b9af-419d426f3e3f","tags":[]},{"id":"poem-38b14d3ce9b971e3846efc24","title":"偈颂 五","author":"文偃","dynasty":"唐","verses":["太阳溢目极玄微，谁人说道我渠非。","句中有路人皆响，觌面难遭第一机。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-e41b953d-8de2-4a55-9c96-e37181c9a53b","tags":[]},{"id":"poem-38b503e22d0ec8df73a6fa64","title":"九江和人赠陈生","author":"李咸用","dynasty":"唐","verses":["天畏斯文坠，凭君助素风。","意深皆可补，句逸不因功。","暮替云愁远，秋惊月占空。","寄家当瀑布，时得笑言同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-acfaa4fa-3c35-4f86-80a6-5108a2436530","tags":[]},{"id":"poem-38bfccb4115725e6469edb9f","title":"唐明堂乐章 宫音","author":"则天皇后","dynasty":"唐","verses":["履艮包群望，居中冠百灵。","万方资广运，庶品荷财成。","神功谅匪测，盛德实难名。","藻奠申诚敬，恭祀表惟馨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-a1c6b056-1c6a-44d9-9e61-9fa5ef3029fb","tags":[]},{"id":"poem-38c2bcada842f629e372c9f2","title":"送越州辛法曹之任","author":"李嘉祐","dynasty":"唐","verses":["但能一官适，莫羡五侯尊。","山色垂趋府，潮声自到门。","缘塘剡溪路，映竹五湖村。","王谢登临处，依依今尚存。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-8c08bd7f-4428-47f3-b4c8-dfb6c845732e","tags":[]},{"id":"poem-38c5f662005c5e7679b027d1","title":"浣溪沙·绿绕红围宋玉墙","author":"向子𬤇","dynasty":"宋","verses":["绿绕红围宋玉墙。","幽兰林下正芬芳。","桃花气暖玉生香。","谁道广平心似铁，艳妆高韵两难忘。","苏州老矣不能狂。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-131","tags":[]},{"id":"poem-38cc901fd1b8fca0a8990e6d","title":"悼陆秘读","author":"释居简","dynasty":"宋","verses":["诸老骑箕上太微，仲谋不似景升儿。","废寻蹊隧千年古，光奋胸襟一段奇。","直敢昧寻嗟枉尺，方宁适义不成规。","泠然差早终无媿，安俟名垂竹帛为。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-813bbd94-8025-43bf-b0f0-4c24a2b28ab3","tags":[]},{"id":"poem-38d033d54a9cbcd04a152483","title":"生查子·金井堕高梧","author":"孙光宪","dynasty":"五代","verses":["金井堕高梧，玉殿笼斜月。","永巷寂无人，敛态愁堪绝。","玉炉寒，香烬灭，还似君恩歇。","翠辇不归来，幽恨将谁说。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-13","tags":[]},{"id":"poem-38d2b35e346be2c1a97a4096","title":"陈情上知己","author":"刘得仁","dynasty":"唐","verses":["性与才俱拙，名场迹甚微。","久居颜亦厚，独立事多非。","刻骨搜新句，无人悯白衣。","明时自堪恋，不是不知机。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2e0ac513-c652-4631-b893-d23c84b7b059","tags":[]},{"id":"poem-38d8a5b761787fd217b5ebbc","title":"公子家","author":"聂夷中","dynasty":"唐","verses":["种花满西园，花发青楼道。","花下一禾生，去之为恶草。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ba1417d6-912a-4606-a798-d8971da31a7e","tags":["写人","讽刺","写人诗"]},{"id":"poem-38e72b7714ab257327357846","title":"闻徐师川自京师还豫章","author":"林之奇","dynasty":"宋","verses":["九衢尘里无停舟，君居陋巷不出游。","满城恶少弋凫雁，对面故人风马牛。","别后天寒灯火夜，归来眠冷江湖秋。","冯驩老大食不饱，起视八荒徒蒯缑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-813e790e-8d6e-43f7-b099-55bfbc91fa8e","tags":[]},{"id":"poem-38eba11ffbadd4e74fbdbcb5","title":"河渎神·凉月转雕阑","author":"纳兰性德","dynasty":"清","verses":["凉月转雕阑，萧萧木叶声干。","银灯飘落琐窗闲，枕屏几叠秋山。","朔风吹透青缣被，药炉火暖初沸。","清漏沉沉无寐，为伊判得憔悴。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-80","tags":[]},{"id":"poem-38f464f8947c29438c0b096a","title":"送友人还洛","author":"李端","dynasty":"唐","verses":["去国渡关河，蝉鸣古树多。","平原正超忽，行子复蹉跎。","去事不可想，旧游难再过。","何当嵩岳下，相见在烟萝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0e58b1d3-ae22-41da-9995-93c3d985e01c","tags":[]},{"id":"poem-38faf4000543bbe073b0553e","title":"禁烟作","author":"牟融","dynasty":"唐","verses":["柳拖金缕拂朱栏，花扑香尘满绣鞍。","尊酒临风酬令节，越罗衣薄觉春寒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7a7c5b6b-7d8b-40fd-a4f1-1ab8962a0826","tags":[]},{"id":"poem-38fcaaeb87b107815cf33e62","title":"宫词  其六八","author":"张公庠","dynasty":"宋","verses":["长乐疏钟常送月，灵和垂柳只从风。","还知天上人难老，颜色年年不减红。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a503e3a6-1456-4880-827d-2b307edc6f14","tags":[]},{"id":"poem-3902be1abada0c61be8611d9","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(外)休皱双眉，听俺从头说仔细。","我在东瓯发足，渡足登舟，一梦跷蹊。","(生)梦见甚的？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8348","tags":[]},{"id":"poem-39080717eba27f4d4e61ab68","title":"车邻","author":"佚名","dynasty":"先秦","verses":["有车邻邻，有马白颠。未见君子，寺人之令。","阪有漆，隰有栗。既见君子，并坐鼓瑟。今者不乐，逝者其耋。","阪有桑，隰有杨。既见君子，并坐鼓簧。今者不乐，逝者其亡。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-125","tags":[]},{"id":"poem-3908de85c48b3c9671242212","title":"句","author":"李元翁","dynasty":"宋","verses":["玉华野人多病恼，独守寒炉煨芋魁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-8075a351-0e52-4ab2-a89b-e2cf2c67398c","tags":[]},{"id":"poem-391377292f556c0b250a0ca7","title":"酹江月・念奴娇·一年好处","author":"曾协","dynasty":"宋","verses":["一年好处，是霜轻尘敛，山川如洗。","晚菊留花供燕赏，金缕宝衣销地。","旧观初还，层楼相望，重见升平际。","小春时节，绮罗丛里人醉。","此日武帐贤侯，六年仁政，浃长淮千里。","欲入鹓行仍缓带，聊抚竹西歌吹。","紫塞烟清，玉关人老，宜趣朝天骑。","香尘归路，旧游回首应记。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-594","tags":[]},{"id":"poem-3916c40ca4df92c5dd73b94f","title":"醉歌","author":"开宝中江南叟","dynasty":"唐","verses":["蓝采禾，蓝采禾，（《江南野史》卷十首二句作「蓝采采」一句，）尘世纷纷世更多。","争如卖药沽酒饮，归去深崖拍手歌。","（见马令《南唐书》卷十五。","）（〖1〗《江南野史》卷十《陈陶传》：「开宝中常见一叟，角发被褐，与一炼师舁药入城鬻之，获赀则市鲜就炉，二人对饮且唱，旁若无人。","既醉且舞而歌曰〖略〗。","时人见其纵逸，姿貌非常，每饮酒食鲊，疑为陶之夫妇焉。","竟不知所终，或云得仙矣。","」〖2〗马令《南唐书》卷十五《陈陶传》：「开宝中常见一叟，角发被褐，与老媪货药于市，获钱则市鲊对饮，旁若无人，既醉，行舞而歌曰〖略〗。","或疑为陶之夫妇云。","」按：陈陶为大中间人，今存其诗，事迹历历可考。","自大中至开宝，已逾百年。","得仙之说，固属附会，陶即耆寿，恐亦难以存活一百数十年之久，何况当时即为存疑，幷无必证，今列之，另以「开宝中江南叟」列目。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-93fffa6a-ad50-488b-8186-fabb83c797a2","tags":[]},{"id":"poem-3917cfb06b964f36ae434660","title":"渡江云·山空天入海","author":"张炎","dynasty":"宋","verses":["山空天入海，倚楼望极，风急暮潮初。","一帘鸠外雨，几处闲田，隔水动春锄。","新烟禁柳，想如今、绿到西湖。","犹记得、当年深隐，门掩两三株。","愁余。","荒洲古溆，断梗疏萍，更漂流何处。","空自觉、围羞带减，影怯灯孤。","常疑即见桃花面，甚近来、翻笑无书。","书纵远，如何也都无。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-259","tags":["宋词三百首","西湖"]},{"id":"poem-39191bcaf5fe7f36613f181c","title":"送僧绎","author":"皎然","dynasty":"唐","verses":["斜日摇扬在柳丝，孤亭寂寂水逶迤。","谁堪别后行人尽，唯有春风起路岐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-dd17e316-87b9-4a64-bdc6-d5cb619bf5e4","tags":[]},{"id":"poem-391af768987fe6057d56677d","title":"秋莺","author":"后主煜","dynasty":"唐","verses":["残莺何事不知秋，横过幽林尚独游。","老舌百般倾耳听，深黄一点入烟流。","栖迟背世同悲鲁，浏亮如笙碎在缑。","莫更留连好归去，露华凄冷蓼花愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-05d03b46-d786-4acf-995e-a20721f16583","tags":[]},{"id":"poem-392776d8075158d8cb28feba","title":"送陈司马","author":"徐凝","dynasty":"唐","verses":["家寄茅洞中，身游越城下。","宁知许长史，不忆陈司马。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b841c536-c468-4588-85bd-196dbc4c1d57","tags":[]},{"id":"poem-3938c50f4e6fb136b8290c23","title":"春堤曲","author":"张籍","dynasty":"唐","verses":["野塘䴔䴖飞树头，绿蒲紫菱盖碧流。","狂客谁家爱云水，日日独来城下游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-0e878fb0-293f-4513-8624-4c57000921ff","tags":[]},{"id":"poem-39408682e1743bb17126efdd","title":"酬万八贺九云门下归溪中作","author":"孙逖","dynasty":"唐","verses":["晚从灵境出，林壑曙云飞。","稍觉清溪尽，回瞻画刹微。","独园余兴在，孤櫂宿心违。","更忆登攀处，天香满袖归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c99ccfe1-f1eb-4573-9c6b-4611359f3df9","tags":[]},{"id":"poem-394452ea61931b38dc87c25b","title":"拜星月・拜星月慢·夜色催更","author":"周邦彦","dynasty":"宋","verses":["夜色催更，清尘收露，小曲幽坊月暗。","竹槛灯窗，识秋娘庭院。","笑相遇，似觉琼枝玉树相倚，暖日明霞光烂。","水眄兰情，总平生稀见。","画图中、旧识春风面。","谁知道、自到瑶台畔。","眷恋雨润云温，苦惊风吹散。","念荒寒、寄宿无人馆。","重门闭、败壁秋虫叹。","怎奈向、一缕相思，隔溪山不断。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-240","tags":["宋词三百首"]},{"id":"poem-39453d2daba3fa4cdc2284be","title":"秋末入匡山船行八首 七","author":"贯休","dynasty":"唐","verses":["南北虽无适，东西亦似萍。","霞根生石片，象迹坏沙汀。","莽莽蒹葭赤，微微蜃蛤腥。","因思范蠡辈，未免亦飘零。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f7bce7a2-640c-4e38-b17c-45b4319ff6e3","tags":["庐山"]},{"id":"poem-394967ef548fd4f503e7edfd","title":"长安少年行 八","author":"李廓","dynasty":"唐","verses":["新年高殿上，始见有光辉。","玉雁排方带，金鹅立仗衣。","酒深和椀赐，马疾打珂飞。","朝下人争看，香街意气归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4684cfef-4203-40fa-b581-6983a4350dc5","tags":[]},{"id":"poem-394be8ac124bc40a483cd7b9","title":"题玄武禅师屋壁","author":"杜甫","dynasty":"唐","verses":["何年顾虎头，满壁画沧州。","赤日石林气，青天江海流。","锡飞常近鹤，杯渡不惊鸥。","似得庐山路，真随惠远游。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題玄武禪師屋壁","tags":[]},{"id":"poem-395dc3eedbe5b84bcca36e9b","title":"三代门 子牙妻","author":"周昙","dynasty":"唐","verses":["陵柏无心竹变秋，不能同戚拟同休。","岁寒焉在空垂涕，覆水如何欲再收。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-26f94d29-6753-4938-94ab-dce13656557f","tags":[]},{"id":"poem-397062a83dbab4c8f7b1a64b","title":"浣溪沙·花月香寒悄夜尘","author":"张泌","dynasty":"五代","verses":["花月香寒悄夜尘，绮筵幽会暗伤神，婵娟依约画屏人。","人不见时还暂语，令才抛后爱微颦，越罗巴锦不胜春。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-33","tags":[]},{"id":"poem-398551ddb3160ed4a04e212f","title":"咏谈容娘","author":"常非月","dynasty":"唐","verses":["举手整花钿，翻身舞锦筵。","马围行处匝，人压看场圆。","歌要齐声和，情教细语传。","不知心大小，容得许多怜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1c5837c9-6ef1-4c77-b669-77663144d23d","tags":[]},{"id":"poem-398d5b33af58d8a258ed9c2c","title":"雁过沙","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦)衙内问我甚情怀？(小生)为何鞋也不穿？(旦)也曾穿着绣鞋。","(小生)敢是挑水卖的？(旦)不曾挑水街头卖。","(众)敢是作歹事？(旦)贞洁妇女。","怎旨作歹事？(小生)被甚么人凌贱你？(旦)被无知兄嫂忒毒害。","(小生)有父母么？(旦)双亲早丧十六载。","(小生)曾有丈夫么？(旦)东床也曾入门来。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8975","tags":[]},{"id":"poem-399bbc8c5a711ce50f0d7984","title":"醉中闻甘州","author":"薛逢","dynasty":"唐","verses":["老听笙歌亦解愁，醉中因遣合甘州。","行追赤岭千山外，坐想黄河一曲流。","日暮岂堪征妇怨，路傍能结旅人愁。","左绵刺史心先死，泪满朱弦催白头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3397705d-20b5-4616-b211-351595710999","tags":["黄河"]},{"id":"poem-399f8aad76942ae0a1a39ea0","title":"八翁吟十首  其四","author":"张载","dynasty":"宋","verses":["老原原上卜年翁，感天功业地天聪。","流言未信成王悟，悟成全得起禾风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8819e8bb-1493-42ee-b3e5-8319d03602b7","tags":[]},{"id":"poem-39a984b3b959aab6d8b7b853","title":"黄伯厚得蒲墨折而为三以书来易戏成二绝  其一","author":"王十朋","dynasty":"宋","verses":["不谓一子墨，忽成三客卿。","君家好兄弟，鼎立并驰名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-d2c27467-42da-4ad3-84ab-74fa6a209db0","tags":[]},{"id":"poem-39aab690ed5ede540021b528","title":"小游仙诗九十八首 一","author":"曹唐","dynasty":"唐","verses":["玉箫金瑟发商声，桑叶枯干海水清。","净埽蓬莱山下路，略邀王母话长生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-1b1ade71-4a27-4fdf-9956-d72894160f51","tags":[]},{"id":"poem-39b2d14b3d623406d1a9f586","title":"满江红·春色匆匆","author":"洪适","dynasty":"宋","verses":["春色匆匆，三分过、二分光景。","吾老矣，坡轮西下，可堪弄影。","曲水流觞时节好，茂林修竹池台永。","望前村、绿柳荫茅檐，云封岭。","蜂蝶闹，烟花整。","百年梦，如俄顷。","这回头陈迹，漫劳深省。","吹竹弹丝谁不爱，焚琴煮鹤人何肯。","尽三觥、歌罢酒来时，风吹醒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-744","tags":[]},{"id":"poem-39bb0e550f839c5af5112c30","title":"旦","author":"无名氏《张协状元》","dynasty":"元","verses":["奴家是状元浑家。","(净)慢行，慢行，怕头上珠牌脱下来。","(末)又道路无拾遗。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2656","tags":[]},{"id":"poem-39bb72670557b3cc5b2bf2bb","title":"北新水令","author":"萧德祥《小孙屠》","dynasty":"元","verses":["梦魂中只听得雨滋滋，元来是死生别处。","浑身上都破损，疼痛怎支吾？朱邦杰，于你有何辜？天怜念小孙屠。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8673","tags":[]},{"id":"poem-39bc49651891eaaf3c49ef0a","title":"菩萨蛮·花明月暗笼轻雾","author":"李煜","dynasty":"五代","verses":["花明月暗笼轻雾，今宵好向郎边去。","铲袜步香阶，手提金缕鞋。","画堂南畔见，一晌偎人颤。","奴为出来难，教郎恣意怜。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-21","tags":[]},{"id":"poem-39c64ab2a483078c4c88e663","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["今日里，今日里，议郎进表，传达上，传达上，圣目看了。","道太师昨日先奏，把乘龙女婿招，多少是好！见有玉音，临降听剖。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5031","tags":[]},{"id":"poem-39c91f1d55e57abf0e2a6ecf","title":"菩萨蛮·飘蓬只逐惊飚转","author":"纳兰性德","dynasty":"清","verses":["飘蓬只逐惊飚转，行人过尽烟光远。","立马认河流，茂陵风雨秋。","寂寥行殿锁，梵呗琉璃火。","塞雁与宫鸦，山深日易斜。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-180","tags":[]},{"id":"poem-39cfd9258f900155b6cda601","title":"菩萨蛮·髻钗初上朝云卷","author":"陈师道","dynasty":"宋","verses":["髻钗初上朝云卷。","眼波翻动眉山远。","一曲杜韦娘。","当年枉断肠。","佳期如好月。","拟满还须缺。","别易见应难。","长须仔细看。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-305","tags":[]},{"id":"poem-39d3b92c1694c1754383b682","title":"上堂水陆","author":"无名氏《张协状元》","dynasty":"元","verses":["衣锦归故乡。","(合)我门得意。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2673","tags":[]},{"id":"poem-39d9e274e8bfd9bab5bb1d7d","title":"三姝媚·湖山经醉惯","author":"吴文英","dynasty":"宋","verses":["湖山经醉惯。","溃春衫、啼痕酒痕无限。","又客长安，叹断襟零袂，尘谁浣。","紫曲门荒，沿败井、风摇青蔓。","对语东邻，犹是曾巢，谢堂双燕。","春梦人间须断。","但怪得、当年梦缘能短。","绣屋秦筝，傍海棠偏爱，夜深开宴。","舞歇歌沈，花未减、红颜先变。","伫久河桥欲去，斜阳泪满。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-80","tags":["宋词三百首"]},{"id":"poem-39dbbb2404ea2590fef8baab","title":"听夜泉","author":"张籍","dynasty":"唐","verses":["细泉深处落，夜久渐闻声。","独起出门听，欲寻当涧行。","还疑隔林远，复畏有风生。","月下长来此，无人亦到明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-92ea24f9-4780-4d8e-857a-3fd7b3778b39","tags":[]},{"id":"poem-39e351296230cb8654bf27c1","title":"秦望山","author":"王镃","dynasty":"宋","verses":["祖龙痴欲望长年，却遣君房渡海船。","枉去蓬山觅丹药，桃源亦自有神仙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-43c0f53e-2167-468d-806f-b7742954e0f4","tags":[]},{"id":"poem-39ffbce121d567d1c434febb","title":"左掖梨花","author":"丘为","dynasty":"唐","verses":["冷艳全欺雪，余香乍入衣。","春风且莫定，吹向玉阶飞。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-左掖梨花","tags":[]},{"id":"poem-3a04c5d2fd4a3a2245900633","title":"元祐己巳岁维扬后斋为亳州使君蒋公写二首  其二","author":"米芾","dynasty":"宋","verses":["小疾翻令吏日闲，明窗尽展古书看。","何须新句能消暑，满腹风云六月寒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-f7c037a4-e2a6-4c5f-83c0-b3a04cc781b4","tags":[]},{"id":"poem-3a0c4cdc3dfa99a87393e9b5","title":"戏题","author":"卢肇","dynasty":"唐","verses":["神女初离碧玉堦，彤云犹拥牡丹鞋。","知道相公怜玉腕，强将纤手整金钗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8a75702b-396d-448c-916d-0dab9cde542b","tags":[]},{"id":"poem-3a0d07f78c0944ddfb3a9780","title":"满庭芳·雨洗花林","author":"洪适","dynasty":"宋","verses":["雨洗花林，春回柳岸，窗间列岫横眉。","老来光景，生怕聚谈稀。","何事扁舟西去，收杖屦、契阔鱼池。","流觞近，诗筒暂歇，焉用虎文彝。","良辰，怀旧事，海棠花下，笑摘垂丝。","叹五年一别，万病难治。","几处绣衣尘迹，歌舞地、乌鹊曾知。","君今去，珠帘暮卷，山雨拂崇碑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-766","tags":[]},{"id":"poem-3a0e71f0236e15049decd55c","title":"凉州行","author":"王建","dynasty":"唐","verses":["凉州四边沙皓皓，汉家无人开旧道。","边头州县尽胡兵，将军别筑防秋城。","万里人家皆已没，年年旌节发西京。","多来中国收妇女，一半生男为汉语。","蕃人旧日不耕犂，相学如今种禾黍。","驱羊亦著锦为衣，为惜毡裘防鬬时。","养蚕缫茧成匹帛，那堪绕帐作旌旗。","城头山鸡鸣角角，洛阳家家学胡乐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-c9159fcd-f025-43f3-b009-1ead5ede5268","tags":[]},{"id":"poem-3a16f0d492034b65f0848856","title":"奉和圣制幸韦嗣立山庄应制","author":"武平一","dynasty":"唐","verses":["鸣銮赫奕下重楼，羽盖逍遥向一丘。","汉日唯闻白衣宠，唐年更覩赤松游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d22ae295-a2f3-4641-9508-9cb7dfae6eb4","tags":[]},{"id":"poem-3a19ca40e68ccd64ced9bf96","title":"郊庙歌辞 禅社首乐章 顺和","author":"贺知章、源乾曜","dynasty":"唐","verses":["至哉含柔德，万物资以生。","常顺称厚载，流谦通变盈。","圣心事能察，增广陈厥诚。","黄祇僾如在，泰折俟咸亨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-089b535d-2b28-486b-b58d-d8a3670c83b2","tags":["抒情","叙事","写景"]},{"id":"poem-3a1d1a9fae88e546ebc1065b","title":"溪村","author":"王镃","dynasty":"宋","verses":["水路随山转，溪晴踏软沙。","斜阳晒鱼网，疏竹露人家。","行蟹上枯岸，饥禽衔落花。","老翁分石坐，闲话到桑麻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-508bee38-23b0-404e-9d2d-6fdfe60c4f7f","tags":[]},{"id":"poem-3a213684b94a3cd652740c27","title":"生查子·寂寞掩朱门","author":"孙光宪","dynasty":"五代","verses":["寂寞掩朱门，正是天将暮。","暗淡小庭中，滴滴梧桐雨。","绣工夫，牵心绪，配尽鸳鸯缕。","待得没人时，偎倚论私语。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-11","tags":[]},{"id":"poem-3a226491d31a00f3c3e1bede","title":"道情诗","author":"王梵志","dynasty":"唐","verses":["我昔未生时，冥冥无所知。","天公强生我，生我复何为？","无衣使我寒，无食使我饥。","还你天公我，还我未生时。","（此首唐释皎然《诗式》卷一《跌宕格二品·骇俗》中引之，郑辑本未收。","）（〖1〗《全唐诗编剧补遗》卷二据《云溪友议》收此诗，今删去。","异文录如次：首句作「天公未生我」，三句「强」作「忽」，五句「使」作「遣」，六句「使」作「遣」，六句「使」作「令」，七句「你」作「尔」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-b2ee8c1d-b8b9-4855-9890-9cca7b6d3f1d","tags":[]},{"id":"poem-3a25f3cc49ae01d5149fd688","title":"渔家傲·青女霜前催得绽","author":"欧阳修","dynasty":"宋","verses":["青女霜前催得绽。","金钿乱散枝头遍。","落帽台高开雅宴。","芳尊满。","挼花吹在流霞面。","桃李三春虽可羡。","莺来蝶去芳心乱。","争似仙潭秋水岸。","香不断。","年年自作茱萸伴。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-663","tags":[]},{"id":"poem-3a26543e33b41edc32617946","title":"宿鉴石浦","author":"杜甫","dynasty":"唐","verses":["早宿宾从劳，仲春江山丽。","飘风过无时，舟檝敢不系。","回塘澹暮色，日没众星嘒。","缺月残未生，青灯死分翳。","穷途多俊异，乱世少恩惠。","鄙夫亦放荡，草草频卒岁。","斯文忧患余，圣哲垂彖系。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cdd25eec-c677-4c60-a12c-784ae0fa932f","tags":[]},{"id":"poem-3a30c2d24b23b146064f2369","title":"南曲风人松","author":"萧德祥《小孙屠》","dynasty":"元","verses":["我一心指望你攻书。","要改换门闾。","如今把奴成抛弃，朝朝望朝朝不至。","好教人鸳衾坦冷落，须闲了我一个枕头儿。","(又唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8616","tags":[]},{"id":"poem-3a3482199cffbf38160114c3","title":"少年游·一生赢得是凄凉","author":"柳永","dynasty":"宋","verses":["一生赢得是凄凉。","追前事、暗心伤。","好天良夜，深屏香被，争忍便相忘。","王孙动是经年去，贪迷恋、有何长。","万种千般，把伊情分，颠倒尽猜量。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-153","tags":[]},{"id":"poem-3a451b491e9f586e9778cd4b","title":"送人出塞","author":"杨凝","dynasty":"唐","verses":["北风吹雨雪，举目已凄凄。","战鬼秋频哭，征鸿夜不栖。","沙平关路直，碛广郡楼低。","此去非东鲁，人多事鼓鼙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0a7a2237-9f1c-485e-a2b7-10d862ff7349","tags":[]},{"id":"poem-3a516c44a0d64016020a00ee","title":"刘泾收得子鸾字帖云是右军余恐是陈子鸾薛绍彭亦云六朝书又得像余时在涟漪答以诗云","author":"米芾","dynasty":"宋","verses":["刘郎收画早甚卑，折枝花草首徐熙。","十年之后始闻道，取吾韩戴为神奇。","迩来白首进道奥，学者信有髓与皮。","始知什袭但遮壁，牛马便可裹敝帷。","峨峨太平老寺主，白纱帽首无冠蕤。","武士后列肃大剑，宫女旁侍颦修眉。","神清眸子知寡欲，齿露唇反法定饥。","世人见服似摩诘，不知六朝居士衣。","后人勿辄乱唐突，梁人笔法了可知。","道子见之必再拜，曹卢何物望藩篱。","本当第一品天下，却缘顾笔在涟漪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-181510f9-8f7b-46ca-b4c4-efbbf8c1ccdd","tags":[]},{"id":"poem-3a58ac5722e108eca5762aa6","title":"挂冠  其二","author":"李瓘","dynasty":"宋","verses":["有手须搴龙衮衣，有头须叩九阶墀。","有口须读离骚词，有腹须饱商山芝。","有身不愿挂绿皮，笑问此身到何之。","石室山之颠，重湖水之湄，陶公云乐夫天命复奚疑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-1f053ea5-f814-4ad9-bfa0-30c4b2b1085e","tags":[]},{"id":"poem-3a64796e6a5729d79ec9c541","title":"立春后三日山行喜雨","author":"赵崇嶓","dynasty":"宋","verses":["穷冬阳为沴，旱气蒸黄埃。","春风三夜动，春雨随风来。","万类萌甲喜，愁人生意开。","我行竟何事，欣尔登崔嵬。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-6c5a4f29-3dc0-4ea3-9903-c90e486de133","tags":[]},{"id":"poem-3a7a3777d26dd99edd8b4181","title":"句","author":"司空图","dynasty":"唐","verses":["忍事敌灾星，物望倾心久。","凶渠破胆频。","鼎饫和方济，台阶润欲平。","夜短猨悲减，风和鹊喜虚。","骅骝思故第，鹦鹉失佳人。","鲸鲵人海涸，魑魅棘林幽。","棋声花院闭，幡影石坛高。","地凉清鹤梦，林静肃僧仪。","晚妆留拜月，春睡更生香。","隔谷见鸡犬，山苗接楚田。","人家寒食月，花影午时天。","官路好禽声，轩车驻晚程。","南楼山最秀，北路邑偏清。","多病形容五十三，谁邻借笏趂朝参。","十年太华无知己，只得虚中两首诗。","看师逸迹两师宜，高适歌行李白诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-313efe5c-4f68-48c6-9ee1-d85613a4c47c","tags":[]},{"id":"poem-3a82f4df9f598a82e1f84291","title":"金陵怀古","author":"李洞","dynasty":"唐","verses":["古来无此战争功，日日戈船卷海风。","一遇灵鼇开睡眼，六朝灰尽九江空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a51bce6a-da65-43b3-9841-65a5e81830de","tags":[]},{"id":"poem-3a85ff0538184f5615603a43","title":"贺圣朝·牡丹盛拆春将暮","author":"杜安世","dynasty":"宋","verses":["牡丹盛拆春将暮。","群芳羞妒。","几时流落在人间，半间仙露。","馨香艳冶，吟看醉赏，叹谁能留住。","莫辞持烛夜深深，怨等闲风雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-919","tags":[]},{"id":"poem-3a8ff8d9f094a6f90d50b782","title":"风流子·秋郊射猎","author":"纳兰性德","dynasty":"清","verses":["平原草枯矣，重阳后，黄叶树骚骚。","记玉勒青丝，落花时节，曾逢拾翠，忽听吹箫。","今来是、烧痕残碧尽，霜影乱红凋。","秋水映空，寒烟如织，皂雕飞处，天惨云高。","人生须行乐，君知否。容易两鬓萧萧。","自与东君作别，刬地无聊。","算功名何许，此身博得。","短衣射虎，沽酒西郊。","便向夕阳影里，倚马挥毫。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-241","tags":[]},{"id":"poem-3aa3435f33108131619a9231","title":"荅道素上人别","author":"皎然","dynasty":"唐","verses":["春色徧远道，寂寞闽中行。","碧水何渺渺，白云亦英英。","离人不可望，日暮芳洲情。","黄鹤有逸翮，翘首白云倾。","欲为山中侣，肯秘辽天声。","蓝缕真子褐，葳蕤近臣缨。","以兹夺尔怀，常恐道不成。","吾门弟子中，不减惠休名。","一性研已远，五言功更精。","从君汗漫游，莫废学无生。","忍草肯摇落，禅枝不枯荣。","采采慰长路，知吾心不轻。","幻情有去住，真性无离别。","留取老桂枝，归来共攀折。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2516d4b3-0226-4238-8134-d7d4e84a86d7","tags":[]},{"id":"poem-3aad18d594adfaf1c31ef3e4","title":"晓鸡","author":"来鹄","dynasty":"唐","verses":["黯黯严城罢鼓鼙，数声相续出寒栖。","不嫌惊破纱窗梦，却怕为妖半夜啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b9e2f62e-e42c-4223-9e16-e976a8ac36ae","tags":[]},{"id":"poem-3abf577f637a1a04592ac3c2","title":"赠剑客","author":"黄损","dynasty":"唐","verses":["杯酒会云林，扶邦志亦深。","晶莹三尺剑，决烈一生心。","见死寻常事，闻冤即往寻。","荆轲不了处，扼腕到如今。","（周本淳校本《诗话总龟》卷二八引《雅言系述》）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-80d662ea-fd25-48ce-90dd-69eae4845986","tags":[]},{"id":"poem-3abf74face115729fcc1694e","title":"宿陕府北楼奉酬崔大夫二首 二","author":"陆畅","dynasty":"唐","verses":["一别朱门三四春，再来应笑尚风尘。","昨宵唯有楼前月，识是谢公诗酒人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-67f1d84b-aa3a-4104-8512-09586d600b28","tags":[]},{"id":"poem-3ac0475d404d7124c9f5559c","title":"秘省伴直","author":"张乔","dynasty":"唐","verses":["乔枝聚暝禽，叠阁锁遥岑。","待月当秋直，看书废夜吟。","残薪留火细，古井下瓶深。","纵欲抄前史，贫难遂此心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-852b7cfa-6c72-433b-b69a-8ce908dc2ed6","tags":[]},{"id":"poem-3ac0f108aa124aad514be0fc","title":"浪淘沙·凉露洗秋空","author":"吕渭老","dynasty":"宋","verses":["凉露洗秋空。","菊径鸣蛩。","水晶帘外月玲珑。","烛蕊双悬人似玉，簌簌啼红。","宋玉在墙东。","醉袖摇风。","心随月影入帘栊。","戏著锦茵天样远，一段愁浓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-83","tags":[]},{"id":"poem-3ac946808eb145d0e4f8fcf9","title":"东封山下宴群臣","author":"张谔","dynasty":"唐","verses":["万里扈封峦，群公遇此欢。","幔城连夜静，霜仗满空寒。","辇路宵烟合，旌门晓月残。","明朝陪圣主，山下礼圆坛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-72d603a6-a1b8-4629-9d88-7fe380b38b3d","tags":[]},{"id":"poem-3accbf8500f306e9a71842dc","title":"西枝邨寻置草堂地夜宿赞公土室二首 一","author":"杜甫","dynasty":"唐","verses":["出郭眄细岑，披榛得微路。","溪行一流水，曲折方屡渡。","赞公汤休徒，好静心迹素。","昨枉霞上作，盛论岩中趣。","怡然共携手，恣意同远步。","扪萝涩先登，陟𪩘眩反顾。","要求阳冈暖，苦陟阴岭沍。","惆怅老大藤，沈吟屈蟠树。","卜居意未展，杖策回且暮。","层巅余落日，早蔓已多露。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-46878bae-9fd8-4808-bb50-ea9bca3cb2bf","tags":[]},{"id":"poem-3ada506cea8e245a33172e75","title":"少年游·重阳过后","author":"晏殊","dynasty":"宋","verses":["重阳过后，西风渐紧，庭树叶纷纷。","朱阑向晓，芙蓉妖艳，特地斗芳新。","霜前月下，斜红淡蕊，明媚欲回春。","莫将琼萼等闲分。","留赠意中人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-475","tags":[]},{"id":"poem-3adacc73e0b28443202b1973","title":"宴清都·绣幄鸳鸯柱","author":"吴文英","dynasty":"宋","verses":["绣幄鸳鸯柱。","红情密，腻云低护秦树。","芳根兼倚，花梢钿合，锦屏人妒。","东风睡足交枝，正梦花、瑶钗燕股。","障滟蜡、满照欢丛，嫠蟾冷落羞度。","人间万感幽单，华清惯浴，春盎风露。","连鬟并暖，同心共结，向承恩处。","凭谁为歌长恨，暗殿锁、秋灯夜语。","叙旧期、不负春盟，红朝翠暮。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-5","tags":["宋词三百首"]},{"id":"poem-3adbc02f0605411b02a63df2","title":"西江月·我性入诸佛性","author":"张伯端","dynasty":"宋","verses":["我性入诸佛性，诸方佛性皆然。","亭亭蟾影照寒泉。","一月千潭普现。","小则毫分莫识，大时遍满三千。","高低不约信方圆。","说甚短长深浅。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-984","tags":[]},{"id":"poem-3ade51d3df9ba94d4210ce2e","title":"次韵江南感事","author":"苏颂","dynasty":"宋","verses":["京洛倦游后，江南感慨多。","壮怀伤岁月，醉眼小山河。","无路通谈说，穷年谩揣摩。","知音如有遇，终采击辕歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-01c941fa-7dcb-4489-92a4-2008e624f649","tags":[]},{"id":"poem-3ae6cc999851111b5c0580f0","title":"好事近·落日水熔金","author":"廖世美","dynasty":"宋","verses":["落日水熔金，天淡暮烟凝碧。","楼上谁家红袖，靠阑干无力。","鸳鸯相对浴红衣，短棹弄长笛。","惊起一双飞去，听波声拍拍。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-625","tags":[]},{"id":"poem-3ae957db1552ec35303020a7","title":"次韵周畏知问讯城东梅坞七首  其一","author":"张栻","dynasty":"宋","verses":["城东幽事如许，一见定胜百闻。","苦雨斜风无柰，断桥流水余芬。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-18bba7ee-1e14-4f20-a6bd-76dd97f2056a","tags":[]},{"id":"poem-3af0278ea8fe32c7ca2c4a57","title":"临江仙·一番荷芰生池沼","author":"尹鹗 六首","dynasty":"五代","verses":["一番荷芰生池沼，槛前风送馨香。","昔年于此伴萧娘，相偎伫立，牵惹叙衷肠。","时逞笑容无限态，还如菡萏争芳。","别来虚遣思悠飏，慵窥往事，金锁小兰房。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-27","tags":[]},{"id":"poem-3af167c0ad8fad55b1fb1f12","title":"中秋夜怀","author":"项斯","dynasty":"唐","verses":["趋驰早晚休，一岁又残秋。","若只如今日，何难至白头。","沧波归处远，旅食尚边愁。","赖见前贤说，穷通不自由。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-6b16e389-f436-4b74-9de0-fd935f949050","tags":[]},{"id":"poem-3af531429e7483b88e5d74d5","title":"送张少府赴夏县","author":"李端","dynasty":"唐","verses":["虽为州县职，还欲抱琴过。","树古闻风早，山枯见雪多。","鸡声连绛市，马色傍黄河。","太守新临郡，还逢五袴歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d455202e-0577-4455-bf2b-0e7040ed9bf4","tags":["黄河"]},{"id":"poem-3b01a1ca3f38993046d81712","title":"峥嵘岭","author":"孟郊","dynasty":"唐","verses":["疏凿顺高下，结构横烟霞。","坐啸郡斋肃，玩奇石路斜。","古树浮绿气，高门结朱华。","始见峥嵘状，仰止逾可嘉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-d3397817-5ef2-43e9-9b0f-cb96e8bab224","tags":[]},{"id":"poem-3b0476f83dd622a7cbbe5fa6","title":"听琴","author":"苏替","dynasty":"唐","verses":["弦中恨起湘山远，指下情多楚峡流。","危槛曲终云影曙，高楼风定烛光秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-1ba636ab-c4b0-4a0f-83ed-dd7a5b4c37cc","tags":[]},{"id":"poem-3b08c4510561c026f90c55e9","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["要你须着这秀才。","(净)我着它伊休要来。","(末)你两个贫胎苦肥。","(生)没紧要休得要系怀。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2600","tags":[]},{"id":"poem-3b1031455057dc584f55a410","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(净)这狗子从小养成，割舍得害他一命？院君休得把人轻。","空有金，空有银，纵有珍珠，休得倚富吞贫。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1881","tags":[]},{"id":"poem-3b25acf0aecd9bbb87b75808","title":"送祖咏","author":"卢象","dynasty":"唐","verses":["田家宜伏腊，岁晏子言归。","石路雪初下，荒村鸡共飞。","东原多烟火，北涧隐寒晖。","满酌野人酒，倦闻邻女机。","胡为困樵采，几日罢朝衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-870e3c4a-aad8-4894-9aea-4b370f85f1c3","tags":[]},{"id":"poem-3b2e06a3ec3d39c0b6d10456","title":"送庐陵王月窗秀才之武昌谒秋壑贾侍郎","author":"宋伯仁","dynasty":"宋","verses":["一緉芒鞋一橐诗，等闲西上欲何之。","青原山下家虽远，黄鹤楼前笛未吹。","秋壑最宜秋到后，月窗当趁月明时。","问君如见调羹手，说寄梅花寄阿谁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1d6b1866-1306-4b88-beb8-e9d2570d9df2","tags":[]},{"id":"poem-3b30619ac1bae074cc1e98ae","title":"子夜吴歌 夏歌","author":"李白","dynasty":"唐","verses":["镜湖三百里，菡萏发荷花。","五月西施采，人看隘若耶。","回舟不待月，归去越王家。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-abb3e465-f10e-43dd-b564-a5de08010478","tags":["清商曲辞","夏天","唐诗三百首","乐府","哲理","写人","荷花"]},{"id":"poem-3b37752ce35907cf90de0250","title":"减字木兰花·红旗高举","author":"黄裳","dynasty":"宋","verses":["红旗高举。","飞出深深杨柳渚。","鼓击春雷。","直破烟波远远回。","欢声震地。","惊退万人争战气。","金碧楼西。","衔得锦标第一归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-627","tags":[]},{"id":"poem-3b3f9867374d2653b51c63d4","title":"雪","author":"王烈","dynasty":"唐","verses":["雪飞当梦蝶，风度几惊人。","半夜一窗晓，平明千树春。","花园应失路，白屋忽为邻。","散入仙厨里，还如云母尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-887ebd54-4d78-41de-8082-a636a184fc0a","tags":[]},{"id":"poem-3b41e1b7b43ee8c645689dbf","title":"月晦","author":"太宗皇帝","dynasty":"唐","verses":["晦魄移中律，凝暄起丽城。","罩云朝盖上，穿露晓珠呈。","笑树花分色，啼枝鸟合声。","披襟欢眺望，极目畅春情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8f179f71-6bfa-4329-9340-2aa81745b2c6","tags":[]},{"id":"poem-3b4210ff619b16f350241fc4","title":"同前换头","author":"无名氏《张协状元》","dynasty":"元","verses":["清晓，侍婢不惜千金，相呼斗百草。","遗珥坠簪，(合)蹙着千秋，不禁笑语声高。","(后)夭桃，遍开浑若烧空，雏禽时叫。","睹景处，觉得奴心烦恼。","(外)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2559","tags":[]},{"id":"poem-3b4bda1c02ad59cef58367fc","title":"登越州城","author":"孙逖","dynasty":"唐","verses":["越嶂绕层城，登临万象清。","封圻沧海合，廛市碧湖明。","晓日渔歌满，芳春櫂唱行。","山风吹美箭，田雨润香秔。","代阅英灵尽，人闲吏隐幷。","赠言王逸少，已见曲池平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b595c6c8-9229-474b-8d80-0cc988c8a1f6","tags":[]},{"id":"poem-3b4cc907e5a503978565375a","title":"送顾少府之永康","author":"马戴","dynasty":"唐","verses":["婺女星边去，春生即有花。","寒关云复雪，古渡草连沙。","宿次吴江晚，行侵日徼斜。","官传梅福政，县顾赤松家。","烧起明山翠，潮回动海霞。","清高宜阅此，莫叹近天涯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b26b953b-531d-40fd-9bdc-e5e923b3bf93","tags":[]},{"id":"poem-3b4dbc218c86ed5c127f260c","title":"赋得暮雨送李胄","author":"韦应物","dynasty":"唐","verses":["楚江微雨里，建业暮钟时。","漠漠帆来重，冥冥鸟去迟。","海门深不见，浦树远含滋。","相送情无限，沾襟比散丝。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-83dcb67c-ccbc-4592-b232-368a6b5275ce","tags":["唐诗三百首","写雨","友情","送别","五言律诗","雨"]},{"id":"poem-3b5f8ac2bcf4962f07de23d8","title":"江神子慢・江城子慢·玉台挂秋月","author":"田为","dynasty":"宋","verses":["玉台挂秋月。","铅素浅，梅花傅香雪。","冰姿洁。","金莲衬、小小凌波罗袜。","雨初歇。","楼外孤鸿声渐远，远山外、行人音信绝。","此恨对语犹难，那堪更寄书说。","教人红销翠减，觉衣宽金缕，都为轻别。","太情切。","消魂处、画角黄昏时节。","声呜咽。","落尽庭花春去也，银蟾迥、无情圆又缺。","恨伊不似馀香，惹鸳鸯结。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-269","tags":["宋词三百首"]},{"id":"poem-3b5f90628262883ca2cc03a0","title":"冷湾","author":"释居简","dynasty":"宋","verses":["怪雨盲风塞冷湾，破头艇子出湖滩。","平生无地酬忠信，独向风波险处看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9bb9f2c9-3f35-4c66-a865-ca6646da3401","tags":[]},{"id":"poem-3b5fe0a15b27e6c13fca92bf","title":"新年作","author":"刘长卿","dynasty":"唐","verses":["乡心新岁切，天畔独潸然。","老至居人下，春归在客先。","岭猨同旦暮，江柳共风烟。","已是长沙傅，从今又几年。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-6556f501-f5b9-4353-bde2-75ec0e1bb616","tags":["唐诗三百首","五言律诗","春节","思乡"]},{"id":"poem-3b66567b61e39f7d75ccb93f","title":"过比干墓","author":"聂夷中","dynasty":"唐","verses":["殷辛帝天下，厌为天下尊。","乾纲既一断，贤愚无二门。","佞是福身本，忠作丧己源。","饿虎不食子，人无骨肉恩。","日影不入地，下埋冤死魂。","腐骨不为土，应作石木根。","余来过此乡，下马吊此坟。","静念君臣间，有道谁敢论。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-366e820c-e3bb-4276-bc10-c8daa92aad19","tags":[]},{"id":"poem-3b6fa53a964c3a111a101df6","title":"斜川日雪观所赋","author":"张栻","dynasty":"宋","verses":["行客念故里，劳者思少休。","如何岁华新，尚尔天南游。","涉五遇佳日，品题自名流。","聊复揩病眼，沙边玩轻鸥。","和风著冠巾，春意动林丘。","缅怀千载人，孤高谅难俦。","亦有一二士，举酒相劝酬。","未知吾故园，草木如此不。","政拙甘下考，智短空百忧。","赐归傥蒙幸，旧盟良可求。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5537c347-aa6a-4ac0-a259-7702f7d80334","tags":[]},{"id":"poem-3b76187033abf32461b8665a","title":"寄友生","author":"李咸用","dynasty":"唐","verses":["交情应不变，何事久离群。","圆月思同步，寒泉忆共闻。","雪霜松色在，风雨雁行分。","每见人来说，窗前改旧文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-434606b8-d921-4fe0-95d9-2deaf7f1d2a4","tags":[]},{"id":"poem-3b83eb26b9a13f4f9d17bdfe","title":"和贾舍人早朝","author":"杜甫","dynasty":"唐","verses":["五夜漏声催晓箭，九重春色醉仙桃。","旌旗日暖龙蛇动，宫殿风微燕雀高。","朝罢香烟携满袖，诗成珠玉在挥毫。","欲知世掌丝纶美，池上于今有凤毛。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-和賈舍人早朝","tags":[]},{"id":"poem-3b9202c215756bfcb132a837","title":"送乐平苗明府得家字","author":"李端","dynasty":"唐","verses":["本自求彭泽，谁云道里赊。","山从石壁断，江向弋阳斜。","暮色随枫树，阴云暗荻花。","诸侯旧调鼎，应重宰臣家。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a0748bf1-95fb-4c94-882d-f60af170e41c","tags":[]},{"id":"poem-3ba53851d3606e3d2cc80850","title":"荷花","author":"江万里","dynasty":"宋","verses":["结亭临水似舟中，夜雨潇潇乱打篷。","荷叶晓看元不湿，却疑误听五更风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-12a115e1-e433-4fc8-8459-6d3c44d75c08","tags":[]},{"id":"poem-3bade4406e17bd40aeb6b685","title":"送旻上人游天台","author":"皎然","dynasty":"唐","verses":["真心不废别，试看越溪清。","知汝机忘尽，春山自有情。","月思华顶宿，云爱石门行。","海近应须泛，无令鸥鹭惊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3b059853-57c0-434e-a748-879d646fb580","tags":[]},{"id":"poem-3bae206e25ad76e972f0afaf","title":"临江仙·金锁重门荒苑静","author":"鹿虔扆","dynasty":"五代","verses":["金锁重门荒苑静，绮窗愁对秋空。","翠华一去寂无踪，玉楼歌吹，声断已随风。","烟月不知人事改，夜阑还照深宫。","藕花相向野塘中，暗伤亡国，清露泣香红。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-13","tags":[]},{"id":"poem-3bb052b4860a08892b467ae3","title":"巫峡","author":"曹松","dynasty":"唐","verses":["巫山苍翠峡通津，下有仙宫楚女真。","不逐彩云归碧落，却为暮雨扑行人。","年年旧事音容在，日日谁家梦想频。","应是荆山留不住，至今犹得覩芳尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-70d15de4-e38a-4449-bd14-86c7b60df075","tags":[]},{"id":"poem-3bb14dd3cae68c990fc2f5b6","title":"天仙子·晴野鹭鸶飞一只","author":"皇甫松","dynasty":"唐","verses":["晴野鹭鸶飞一只，水荭花发秋江碧。","刘郎此日别天仙，登绮席，泪珠滴，十二晚峰高历历。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-16","tags":[]},{"id":"poem-3bb74f9e6327490fe382924e","title":"曹山延寿院","author":"陈岩","dynasty":"宋","verses":["三角坳泓一角亏，其间浊水照摩尼。","风幡不动炉烟直，正是僧禅定起时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-3c77feb9-7b20-4cc3-970e-ccb7a286c4ea","tags":[]},{"id":"poem-3bcb9e2f7fa55d1c9b7bca5a","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["觑着爹颜衰鬓星，痛点点教别泪暗零。","爹爹，我左难右难：误了公婆，被人讥评；撇了亲爹，又没人看承。","(合前)(生唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5253","tags":[]},{"id":"poem-3bd24843e642e6d661e8df96","title":"送崔录事赴宣城","author":"高适","dynasty":"唐","verses":["大国非不理，小官皆用才。","欲行宣城印，住饮洛阳桮。","晚景为人别，长天无鸟廻。","举帆风波渺，倚櫂江山来。","羡尔兼乘兴，芜湖千里开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5a966ed0-e64c-4cd4-9361-c79dbe37c05f","tags":[]},{"id":"poem-3bd3c4e5983c21f3583d49e6","title":"六丑·似东风老大","author":"彭元逊","dynasty":"宋","verses":["似东风老大，那复有、当时风气。","有情不收，江山身是寄。","浩荡何世。","但忆临官道，暂来不住，便出门千里。","痴心指望回风坠。","扇底相逢，钗头微缀。","他家万条千缕，解遮亭障驿，不隔江水。","瓜洲曾舣，等行人岁岁。","日下长秋，城乌夜起。","帐庐好在春睡。","共飞归湖上，草青无地。","雨、春心如腻。","欲待化、丰乐楼前，青门都废。","何人念、流落无几。","点点抟作，雪绵松润，为君泪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-100","tags":["宋词三百首"]},{"id":"poem-3bd457798d4b878e510b86f2","title":"晓发","author":"唐求","dynasty":"唐","verses":["旅馆候天曙，整车趋远程。","几处晓钟断，半桥残月明。","沙上鸟犹在，渡头人未行。","去去古时道，马嘶三两声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-df9e4ccc-8781-44b8-8346-5af01a82a612","tags":[]},{"id":"poem-3bdec42c2fef15ef568724bf","title":"浣溪沙·索得玄珠也是呆","author":"史浩","dynasty":"宋","verses":["索得玄珠也是呆。","人人有分莫胡猜。","顶门一眼镇长开。","路断玉关无辙迹，雪埋葱岭没根栽。","始称达摩不曾来。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-159","tags":[]},{"id":"poem-3bdf53830db5ab0659b386c4","title":"送马戴书记之太原","author":"薛能","dynasty":"唐","verses":["一曲大河声，全家几日行。","从容长约夜，差互忽离城。","镇北胡沙浅，途中霍岳横。","相逢莫已讯，诗雅负雄名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8306e008-e7cb-4030-bdab-dc2a2472e0a2","tags":[]},{"id":"poem-3be196792778bdf1500bde3d","title":"鼓吹曲辞 巫山高","author":"僧齐己","dynasty":"唐","verses":["巫山高，巫女妖。","雨为暮兮云为朝，楚王顦顇魂欲销。","秋猨嗥嗥日将夕，红霞紫烟凝老壁。","千岩万壑花皆坼，但恐芳菲无正色。","不知今古行人行，几人经此无秋情。","云深庙远不可觅，十二峰头插天碧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ee1c6140-7f86-4c71-ac6b-26abdbe9aa12","tags":[]},{"id":"poem-3be8a82b027b2af6188aaf27","title":"浣溪沙·肯把离情容易看","author":"纳兰性德","dynasty":"清","verses":["肯把离情容易看，要从容易见艰难。","难抛往事一般般。","今夜灯前形共影，枕函虚置翠衾单。","更无人与共春寒。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-205","tags":[]},{"id":"poem-3beccf2e8537ee221d8edbef","title":"丑奴儿・采桑子·珠灯璧月年时节","author":"张孝祥","dynasty":"宋","verses":["珠灯璧月年时节，织手同携。","今夕谁知，自拈梅花劝一卮。","逢人问道归来也，日日佳期。","管有来时。","趁得手灯也未迟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-276","tags":[]},{"id":"poem-3becfa2271ebe8ad930d822d","title":"游云顶山晚望","author":"贯休","dynasty":"唐","verses":["云顶聊一望，山灵草木奇。","黔南在何处，堪笑复堪悲。","菊歇香未歇，露繁蝉不饥。","明朝又西去，锦水与峨眉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4b955db8-1d3d-4dc7-bb07-c05213bfb067","tags":[]},{"id":"poem-3bee8abcda72dba518380026","title":"满朝欢·花隔铜壶","author":"柳永","dynasty":"宋","verses":["花隔铜壶，露晞金掌，都门十二清晓。","帝里风光烂漫，偏爱春杪。","烟轻昼永，引莺啭上林，鱼游灵沼。","巷陌乍晴，香尘染惹，垂杨芳草。","因念秦楼彩凤，楚观朝云，往惜曾迷歌笑。","别来岁久，偶忆欢盟重到。","人面桃花，未知何处，但掩朱扉悄悄。","尽日伫立无言，赢得凄凉怀抱。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-69","tags":[]},{"id":"poem-3bfbbce41544bdac7555af7c","title":"春雨","author":"李商隐","dynasty":"唐","verses":["怅卧新春白袷衣，白门寥落意多违。","红楼隔雨相望冷，珠箔飘灯独自归。","远路应悲春晼晚，残宵犹得梦依稀。","玉珰缄札何由达，万里云罗一雁飞。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8331c76b-a250-4d07-9c28-b8a456e0974c","tags":["唐诗三百首","写雨","七言律诗","爱情","雨"]},{"id":"poem-3bfdc524971a0ec8d79431e1","title":"拟齐梁体寄冯使君三首 二","author":"贯休","dynasty":"唐","verses":["露益蝉声长，蕙兰垂紫带。","清吟代明月，孤云忽为盖。","伊余石林人，本是烧畬辈。","频接谢公棋，输多未曾赛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3dc179e3-6b97-4513-9d55-8b9cdb6673e6","tags":[]},{"id":"poem-3c03bdad2c701ed4db61526f","title":"酬谢司直晦斋寄宋湖州见柬  其一","author":"释居简","dynasty":"宋","verses":["春无十日好，又是去堂堂。","柳借鵞黄重，花消蝶粉香。","清和宜晚步，零落课残芳。","北牖华风煖，朝来尚宠光。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-6176717d-ba05-4505-8515-93c22b2af038","tags":[]},{"id":"poem-3c141cecbf0fb91b08d2db5c","title":"幺","author":"杨景贤","dynasty":"元","verses":["他道是父姓陈，母姓殷。","为官为吏是当军？(唐僧云)我父亲任洪州太守。","(夫人唱)几年上此间来治民？(唐僧云)贞观三年八月间，被贼人劫杀在江中了也。","(夫人唱)则一句道的我心迷眼晕，他道是江上遇着强人。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7962","tags":[]},{"id":"poem-3c171ecad2558846e0b76b60","title":"赠别王侍御赴任陕州司马","author":"张籍","dynasty":"唐","verses":["京城在处闲人少，唯共君行并马蹄。","更和诗篇名最出，时倾杯酒户常齐。","同趋阙下听钟漏，独向军前闻鼓鼙。","今日春明门外别，更无因得到街西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a8765dbf-31c4-46a6-bd1e-0accbdc6fe95","tags":[]},{"id":"poem-3c2583d219e68fd992d05be4","title":"自长沙至醴陵田皆垦辟有筑室而居者","author":"李纲","dynasty":"宋","verses":["年来盗贼若冰销，襁负归民满四郊。","烟雨一犁初破土，江村环堵且诛茅。","疮痍不扰生新肉，燕雀无虞返旧巢。","安集勤斯徒自叹，勿令虎兕更咆哮。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-59c25947-3b60-4988-8e55-8948e5449a8a","tags":[]},{"id":"poem-3c33cfcb5ffd84977a4c30af","title":"更漏子·钟鼓寒","author":"韦庄","dynasty":"五代","verses":["钟鼓寒，楼阁暝，月照古桐金井。","深院闭，小庭空，落花香露红。","烟柳重，春雾薄，灯背水窗高阁。","闲倚户，暗沾衣，待郎郎不归。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-22","tags":[]},{"id":"poem-3c3ba33405c7e2c6d51abc6c","title":"句","author":"庆书记","dynasty":"宋","verses":["人从晓月残边去，路入云山瘦处行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-4af08ba3-ee50-421a-8ae0-4351f1e51f22","tags":[]},{"id":"poem-3c41ab5f86c58f9abf136bb7","title":"郊庙歌辞 明皇祀圜丘乐章 豫和","author":"不详","dynasty":"唐","verses":["大号成命，思文配天。","神光肸蚃，龙驾言旋。","眇眇阊阖，昭昭上玄。","俾昌而大，于斯万年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-caf25139-a8d2-4ba1-83e2-2fcfe60ff6a9","tags":[]},{"id":"poem-3c430a41d3f34873d8cfd716","title":"诗品二十四则 洗炼","author":"司空图","dynasty":"唐","verses":["犹鑛出金，如铅出银。","超心炼冶，绝爱[缁]磷。","空潭泻春，古镜照神。","体素储洁，乘月返真。","载瞻星辰，载歌幽人。","流水今日，明月前身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ef2f3ad2-6df1-4519-ab0e-ae19a456cb6b","tags":[]},{"id":"poem-3c4d2861bebc437ea7fa3f1b","title":"定西番·汉使昔年离别","author":"温庭筠","dynasty":"唐","verses":["汉使昔年离别。","攀弱柳，折寒梅，上高台。","千里玉关春雪，雁来人不来。","羌笛一声愁绝，月徘徊。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-26","tags":[]},{"id":"poem-3c59e374f3453fb40d6a9deb","title":"朝中措·吴松江影漾清辉","author":"张抡","dynasty":"宋","verses":["吴松江影漾清辉。","山远翠光微。","杨柳风轻日永，桃花浪暖鱼肥。","东来西往。","随情任性，本自无机。","何事沙边鸥鹭，一声欸乃惊飞。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-943","tags":[]},{"id":"poem-3c5ae83c47a71796302b5326","title":"前腔换头","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["媒婆告相公知：恨那人作怪跷蹊。","道始得及第，纵有花貌休提。","骂相公，骂小娘……。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5012","tags":[]},{"id":"poem-3c5be5ea139539b909cce82f","title":"生查子·见汝小溪湾","author":"王质","dynasty":"宋","verses":["见汝小溪湾，修竹连疏影。","林杪动风声，惊下毵毵粉。","见汝大江郊，高浪摇枯本。","飞雪密封枝，直到斜阳醒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-308","tags":[]}];
